import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'

import type { AgentCard, AgentTally, Check, Gate, Layout, LogLine, Loop, Main, Turn, Usage, View } from '../types'
import {
  LOG_WHO_MAX,
  DEFAULT_ABORTS,
  DEFAULT_AGENTS,
  DEFAULT_CACHE,
  DEFAULT_CONTEXT,
  DEFAULT_GATE,
  DEFAULT_MAIN,
  DEFAULT_OPTIONS,
  DEFAULT_PROMPT,
  DEFAULT_TESTS,
  DEFAULT_TURN,
  DEFAULT_USAGE,
  DEFAULT_VIEW,
  EDIT_TOOLS,
  SAMPLE_MS,
  SCHEMA_VERSION,
  admitCards,
  afterCall,
  applyStep,
  bucketOf,
  cardTitle,
  describeInput,
  fmtDuration,
  gateSummary,
  gauge,
  gridOrder,
  isSampling,
  listOf,
  normalize,
  normalizeCard,
  normalizeDeck,
  normalizeGate,
  normalizeLog,
  noteTool,
  PALETTES,
  parseConfig,
  promptLine,
  receiptOf,
  redact,
  recordCheck,
  reduceDeck,
  settleCheck,
  shorten,
  stepLoop,
  tallyByType,
  totals,
} from './core'
import type { Config, Deck, DeckEvent, DeckOptions } from './core'
import { draw } from './draw'

const PANE = 'sessiondeck'
const TITLE = 'Sessiondeck'
const PANE_COLUMNS = 66


// ---------------------------------------------------------------- state

const meta = atom({ plugin: 'sessiondeck', key: 'meta' } as const, { schemaVersion: SCHEMA_VERSION })
const main = atom({ plugin: 'sessiondeck', key: 'main' } as const, DEFAULT_MAIN)
const usage = atom({ plugin: 'sessiondeck', key: 'usage' } as const, DEFAULT_USAGE)
const gate = atom({ plugin: 'sessiondeck', key: 'gate' } as const, DEFAULT_GATE)
const agents = atom({ plugin: 'sessiondeck', key: 'agents' } as const, [])
const loops = atom({ plugin: 'sessiondeck', key: 'loops' } as const, [])
const log = atom({ plugin: 'sessiondeck', key: 'log' } as const, [])
const turn = atom({ plugin: 'sessiondeck', key: 'turn' } as const, DEFAULT_TURN)
const receipt = atom({ plugin: 'sessiondeck', key: 'receipt' } as const, null)
const view = atom({ plugin: 'sessiondeck', key: 'view' } as const, DEFAULT_VIEW)
const prompt = atom({ plugin: 'sessiondeck', key: 'prompt' } as const, DEFAULT_PROMPT)
const cache = atom({ plugin: 'sessiondeck', key: 'cache' } as const, DEFAULT_CACHE)
const tools = atom({ plugin: 'sessiondeck', key: 'tools' } as const, {})
const hotFiles = atom({ plugin: 'sessiondeck', key: 'hotFiles' } as const, {})
const tests = atom({ plugin: 'sessiondeck', key: 'tests' } as const, DEFAULT_TESTS)
const aborts = atom({ plugin: 'sessiondeck', key: 'aborts' } as const, DEFAULT_ABORTS)
const agentStats = atom({ plugin: 'sessiondeck', key: 'agentStats' } as const, DEFAULT_AGENTS)
const context = atom({ plugin: 'sessiondeck', key: 'context' } as const, DEFAULT_CONTEXT)

// Every read goes through these, so a value saved under an older shape still reads.
async function getMain($: EngineInterface): Promise<Main> {
  return normalize(DEFAULT_MAIN, await read($, main))
}
async function getUsage($: EngineInterface): Promise<Usage> {
  return normalize(DEFAULT_USAGE, await read($, usage))
}
async function getGate($: EngineInterface): Promise<Gate> {
  return normalizeGate(await read($, gate))
}
async function getCards($: EngineInterface): Promise<AgentCard[]> {
  return listOf<unknown>(await read($, agents)).map(normalizeCard)
}
async function getLoops($: EngineInterface): Promise<Loop[]> {
  return listOf<Loop>(await read($, loops))
}
async function getLog($: EngineInterface): Promise<LogLine[]> {
  return normalizeLog(await read($, log))
}
async function getTurn($: EngineInterface): Promise<Turn> {
  return normalize(DEFAULT_TURN, await read($, turn))
}
async function getView($: EngineInterface): Promise<View> {
  return normalize(DEFAULT_VIEW, await read($, view))
}
async function getDeck($: EngineInterface): Promise<Deck> {
  const [p, c, t, h, ts, a, ag, cx] = await Promise.all([
    read($, prompt),
    read($, cache),
    read($, tools),
    read($, hotFiles),
    read($, tests),
    read($, aborts),
    read($, agentStats),
    read($, context),
  ])
  return normalizeDeck({ prompt: p, cache: c, tools: t, hotFiles: h, tests: ts, aborts: a, agents: ag, context: cx })
}

// One log line per load says the deck stopped updating; repeating it every call would flood the log.
let reported = false

/** A deck slice's failure stays in the deck: the call that fed it still resolves. */
async function safely($: EngineInterface, work: () => Promise<unknown>): Promise<void> {
  try {
    await work()
  } catch (err) {
    if (reported) return
    reported = true
    try {
      await say($, 'sessiondeck', `deck update failed: ${String(err).slice(0, 80)}`, 'error')
    } catch {}
  }
}

// Each write is computed from a whole-deck read, so two calls settling together would
// otherwise each write from the same read and one would be lost.
let queue: Promise<unknown> = Promise.resolve()
function serial<T>(work: () => Promise<T>): Promise<T> {
  const run = queue.then(work)
  queue = run.catch(() => undefined)
  return run
}

function apply($: EngineInterface, e: DeckEvent, opts: DeckOptions = DEFAULT_OPTIONS): Promise<void> {
  return serial(async () => {
    const d = await getDeck($)
    const n = reduceDeck(d, e, opts)
    if (n.prompt !== d.prompt) await update($, prompt, () => n.prompt)
    if (n.cache !== d.cache) await update($, cache, () => n.cache)
    if (n.tools !== d.tools) await update($, tools, () => n.tools)
    if (n.hotFiles !== d.hotFiles) await update($, hotFiles, () => n.hotFiles)
    if (n.tests !== d.tests) await update($, tests, () => n.tests)
    if (n.aborts !== d.aborts) await update($, aborts, () => n.aborts)
    if (n.agents !== d.agents) await update($, agentStats, () => n.agents)
    if (n.context !== d.context) await update($, context, () => n.context)
  })
}

async function admit($: EngineInterface, cap: number) {
  await serial(async () => {
    const [cards, d] = await Promise.all([getCards($), getDeck($)])
    if (admitCards(cards, d.agents.byType, cap).cards === cards) return
    // Card writes outside serial (spawn, step, status) can land mid-update; update re-runs
    // this on the fresh list, so the last run's folded matches the list it wrote.
    let folded: Record<string, AgentTally> | null = null
    await update($, agents, list => {
      const fresh = listOf<unknown>(list).map(normalizeCard)
      const kept = admitCards(fresh, d.agents.byType, cap)
      folded = kept.cards === fresh ? null : kept.folded
      return kept.cards
    })
    const byType = folded
    if (byType) await update($, agentStats, () => ({ ...d.agents, byType }))
  })
}

let sampler: Timer | null = null

async function ensureSampler($: EngineInterface) {
  if (sampler) return
  const [d, cards] = await Promise.all([getDeck($), getCards($)])
  if (sampler || !isSampling(d.prompt, cards)) return
  sampler = $.clock.every(SAMPLE_MS, () => void safely($, () => tick($)))
}

async function tick($: EngineInterface) {
  const [d, cards] = await Promise.all([getDeck($), getCards($)])
  if (!isSampling(d.prompt, cards)) {
    sampler?.cancel()
    sampler = null
    return
  }
  const { spawning: _, ...counts } = totals(tallyByType(cards, d.agents.byType))
  await apply($, { kind: 'tick', at: await $.clock.now(), counts })
}

/** A stored shape older than this build's: drop what cannot be read, keep the rest. */
async function migrate($: EngineInterface) {
  const m = await read($, meta)
  if ((m?.schemaVersion ?? 0) >= SCHEMA_VERSION) return
  await update($, log, list => normalizeLog(list))
  await update($, agents, list => listOf<unknown>(list).map(normalizeCard))
  await update($, gate, g => normalizeGate(g))
  await update($, meta, () => ({ schemaVersion: SCHEMA_VERSION }))
}

async function say($: EngineInterface, who: string, text: string, kind: LogLine['kind'] = 'info', agentId: string | null = null) {
  const line: LogLine = { at: await $.clock.now(), who, text, kind, agentId }
  await update($, log, list => [...normalizeLog(list), line].slice(-60))
}

/** Every agent this session, the cards the cap folded into agentStats included. */
async function agentCounts($: EngineInterface): Promise<{ live: number; total: number }> {
  const [cards, d] = await Promise.all([getCards($), getDeck($)])
  const t = totals(tallyByType(cards, d.agents.byType))
  return { live: t.spawning + t.running, total: t.spawning + t.running + t.done + t.error }
}

async function refreshStatus($: EngineInterface, cfg: Config) {
  if (!cfg.statusLine) return $.ui.status(undefined)
  const [u, g, a] = await Promise.all([getUsage($), getGate($), agentCounts($)])
  const s = gateSummary(g)
  const parts = [
    u.pct !== null ? `ctx ${Math.round(u.pct)}%` : null,
    a.total > 0 ? `agents ${a.live}/${a.total}` : null,
    s.deny > 0 ? `denied ${s.deny}` : null,
  ]
  // Only fields with something to say; with none, no status entry at all.
  const shown = parts.filter(Boolean)
  $.ui.status(shown.length > 0 ? shown.join(' · ') : undefined)
}

async function whoIs($: EngineInterface, agentId: string | undefined) {
  if (!agentId) return 'main'
  const card = (await getCards($)).find(c => c.id === agentId)
  return card ? shorten(cardTitle(card), LOG_WHO_MAX) : 'agent'
}

async function openPane($: EngineInterface) {
  // columns apply when docked beside the transcript, rows when seated inline above the prompt.
  return $.ui.open({ id: PANE, title: TITLE, columns: PANE_COLUMNS, rows: 8 })
}

async function resetAll($: EngineInterface) {
  // Serial with apply: a deck write in flight would otherwise land after the reset.
  await serial(async () => {
    await update($, main, m => ({ ...DEFAULT_MAIN, model: normalize(DEFAULT_MAIN, m).model, mode: normalize(DEFAULT_MAIN, m).mode }))
    await update($, gate, () => DEFAULT_GATE)
    await update($, agents, () => [])
    await update($, loops, () => [])
    await update($, log, () => [])
    await update($, turn, () => DEFAULT_TURN)
    await update($, receipt, () => null)
    await update($, view, () => DEFAULT_VIEW)
    await update($, prompt, () => DEFAULT_PROMPT)
    await update($, cache, () => DEFAULT_CACHE)
    await update($, tools, () => ({}))
    await update($, hotFiles, () => ({}))
    await update($, tests, () => DEFAULT_TESTS)
    await update($, aborts, () => DEFAULT_ABORTS)
    await update($, agentStats, () => DEFAULT_AGENTS)
    await update($, context, () => DEFAULT_CONTEXT)
    // The context gauge waits for the next measurement rather than showing the pre-clear fill.
    await update($, usage, x => ({ ...normalize(DEFAULT_USAGE, x), pct: null, tokens: null }))
  })
}

/** The session's cost read fresh, not from the last measurement: the receipt subtracts two of these. */
async function costNow($: EngineInterface): Promise<number | null> {
  const u = await $.session.usage().catch(() => null)
  return u?.cost?.usd ?? null
}

async function noteMode($: EngineInterface, mode: string | undefined) {
  if (mode) await update($, main, m => (normalize(DEFAULT_MAIN, m).mode === mode ? normalize(DEFAULT_MAIN, m) : { ...normalize(DEFAULT_MAIN, m), mode }))
}

// ---------------------------------------------------------------- hooks

export const register: Register = (on, options) => {
  const cfg = parseConfig(options)
  const C = PALETTES[cfg.palette]
  const deckOptions: DeckOptions = { testPattern: cfg.testPattern }
  // tool.check carries no loop id; the tool.call around it does, keyed by the call's id.
  const callLoop = new Map<string, string | null>()

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'sessiondeck',
      description: 'Sessiondeck, the live agent dashboard: open, close, reset, or set the layout',
      argumentHint: '[open|close|reset|layout auto|compact|wide|mini]',
    })
    await migrate($)
    if (cfg.isTestPatternFallback) await say($, 'sessiondeck', 'testPattern did not compile; using the default', 'error')
    // A host without usage (headless, an SDK host, a session not yet bound) just starts without it.
    const u = await $.session.usage().catch(() => null)
    if (u) {
      await update($, usage, x => ({
        ...normalize(DEFAULT_USAGE, x),
        pct: u.context.percent ?? null,
        tokens: u.context.tokens ?? null,
        window: u.context.window,
        costUsd: u.cost?.usd ?? null,
        limits: u.rateLimits.map(r => ({ kind: r.kind, pct: r.percentUsed })),
      }))
    }
    if (cfg.openOnStart) void openPane($).catch(() => undefined)
    await refreshStatus($, cfg)
    return next(e)
  })

  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      await resetAll($)
      await refreshStatus($, cfg)
    }
    return next(e)
  })

  on('command.run', { command: 'sessiondeck' }, async ($, e) => {
    const [verb = 'open', arg = ''] = e.args.trim().split(/\s+/)
    if (verb === 'close') {
      await $.ui.close({ id: PANE })
      return { text: 'Sessiondeck closed.' }
    }
    if (verb === 'reset') {
      await resetAll($)
      await refreshStatus($, cfg)
      return { text: 'Sessiondeck reset.' }
    }
    if (verb === 'layout') {
      const layout: Layout | null = arg === 'compact' || arg === 'wide' || arg === 'auto' || arg === 'mini' ? arg : null
      if (!layout) return { text: 'Usage: /sessiondeck layout auto|compact|wide|mini' }
      await update($, view, v => ({ ...normalize(DEFAULT_VIEW, v), layout }))
      const opened = await openPane($)
      return { text: opened.isPlaced ? `Sessiondeck layout: ${layout}.` : `Layout set to ${layout}; the pane is not shown yet: ${opened.reason}` }
    }
    const opened = await openPane($)
    if (!opened.isPlaced) return { text: `Sessiondeck is not shown yet: ${opened.reason}` }
    return { text: 'Sessiondeck opened. Focus it with ctrl+x tab; 1-9 select agents, n/b walk past nine, x clears; f/s/o open the gate rows.' }
  })

  on('classic.UserPromptSubmit', async ($, e, next) => {
    await noteMode($, e.permission_mode)
    const r = await next(e)
    await safely($, () => apply($, { kind: 'prompt', text: e.prompt }, deckOptions))
    return r
  })

  on('turn.start', async ($, e, next) => {
    const [now, cost, a] = await Promise.all([$.clock.now(), costNow($), agentCounts($)])
    await update($, turn, () => ({ ...DEFAULT_TURN, startedAt: now, costAtStart: cost, agentsAtStart: a.total }))
    await update($, main, m => ({ ...normalize(DEFAULT_MAIN, m), isRunning: true }))
    if (e.text) {
      const p = promptLine(redact(e.text))
      await say($, p.who, p.text)
    }
    const r = await next(e)
    await safely($, async () => {
      await apply($, { kind: 'turn.start', at: now, turnId: e.turnId, text: e.text }, deckOptions)
      await ensureSampler($)
    })
    return r
  })

  on('turn.step', async function* ($, e, next) {
    // The main loop's model is known when its request starts; a long first request shouldn't read "—".
    if (!e.agentId) {
      await update($, main, m => {
        const x = normalize(DEFAULT_MAIN, m)
        return { ...x, model: e.model, effort: String(e.effort ?? x.effort), steps: x.steps + 1 }
      })
      const result = yield* next(e)
      await safely($, () => apply($, { kind: 'step', agentId: null, usage: result.usage }, deckOptions))
      return result
    }
    const result = yield* next(e)
    const id = e.agentId
    const cards = await getCards($)
    if (cards.some(c => c.id === id)) {
      const step = { model: e.model, usage: result.usage, stopReason: result.stopReason }
      await update($, agents, list => listOf<unknown>(list).map(normalizeCard).map(c => (c.id === id ? applyStep(c, step) : c)))
      if (result.stopReason === 'max_tokens') await say($, await whoIs($, id), 'hit max_tokens', 'error', id)
    } else {
      const now = await $.clock.now()
      await update($, loops, l => stepLoop(listOf<Loop>(l), id, now))
    }
    return result
  })

  on('session.measure', async ($, e, next) => {
    await update($, usage, x => ({
      ...normalize(DEFAULT_USAGE, x),
      pct: e.context.percent ?? null,
      tokens: e.context.tokens ?? null,
      window: e.context.window,
      costUsd: e.cost?.usd ?? null,
      limits: e.rateLimits.map(r => ({ kind: r.kind, pct: r.percentUsed })),
    }))
    if (e.changed.includes('context')) await refreshStatus($, cfg)
    const r = await next(e)
    await safely($, async () => apply($, { kind: 'measure', percent: e.context.percent ?? null, at: await $.clock.now() }, deckOptions))
    return r
  })

  on('session.compact', async ($, e, next) => {
    const done = await next(e)
    if (!e.agentId && e.trigger !== 'precompute') {
      const now = await $.clock.now()
      await update($, usage, x => {
        const u = normalize(DEFAULT_USAGE, x)
        return { ...u, compactions: u.compactions + 1, lastCompactAt: now }
      })
      await say($, 'main', `context compacted (${e.trigger})`)
      await safely($, () => apply($, { kind: 'compact', at: now }, deckOptions))
    }
    return done
  })

  on('tool.check', async ($, e, next) => {
    const verdict = await next(e)
    if (e.tool_use_id) {
      const check: Check = {
        id: e.tool_use_id,
        tool: e.tool,
        bucket: bucketOf(e.tool),
        verdict: verdict.decision === 'allow' ? 'rule' : verdict.decision,
        inSubagent: Boolean(callLoop.get(e.tool_use_id)),
        detail: shorten(describeInput(e.tool, e.input), 90),
        at: await $.clock.now(),
      }
      await update($, gate, g => recordCheck(normalizeGate(g), check))
      // The status line updates when the call settles; only a refusal ends here.
      if (verdict.decision === 'deny') {
        await say($, 'gate', `denied by rule · ${check.detail}`, 'error')
        await refreshStatus($, cfg)
      }
    }
    return verdict
  })

  on('tool.call', async ($, e, next) => {
    callLoop.set(e.tool_use_id, e.agentId ?? null)
    const calledAt = await $.clock.now()
    const ran = await next(e).finally(() => callLoop.delete(e.tool_use_id))
    const didRun = ran.deny === undefined
    // Settle this call's pending ask, if it had one; skip the write (and the redraw) otherwise.
    const g0 = await getGate($)
    const isSettled = settleCheck(g0, e.tool_use_id, didRun) !== g0
    if (isSettled) await update($, gate, g => settleCheck(normalizeGate(g), e.tool_use_id, didRun))
    await safely($, async () => {
      const settledAt = await $.clock.now()
      await apply($, {
        kind: 'tool',
        tool: e.tool,
        agentId: e.agentId ?? null,
        outcome: !didRun ? 'denied' : ran.isError ? 'error' : 'ok',
        // A call that waited on an ask measures the human, not the tool.
        ms: isSettled ? null : settledAt - calledAt,
        filePath: e.tool === 'Edit' || e.tool === 'Write' ? e.file_path : e.tool === 'NotebookEdit' ? e.notebook_path : null,
        command: e.tool === 'Bash' ? e.command : null,
        at: settledAt,
      }, deckOptions)
    })
    if (e.tool === 'Agent') {
      if (isSettled) await refreshStatus($, cfg)
      return ran
    }
    const hasFailed = didRun && ran.isError === true
    const isEdit = !hasFailed && didRun && EDIT_TOOLS.has(e.tool)
    const t0 = await getTurn($)
    if (isEdit || hasFailed || (!e.agentId && t0.errorStreak > 0)) {
      await update($, turn, t => afterCall(normalize(DEFAULT_TURN, t), { inSubagent: Boolean(e.agentId), hasFailed, isEdit }))
    }
    const text = shorten(describeInput(e.tool, e), 64)
    if (e.agentId) {
      const id = e.agentId
      await update($, agents, list =>
        listOf<unknown>(list)
          .map(normalizeCard)
          .map(c => (c.id === id ? noteTool(c, { tool: e.tool, text, isError: hasFailed || ran.deny !== undefined }) : c)),
      )
    }
    // The log keeps what is worth a glance: refusals, errors and edits; the rest is on the cards.
    if (ran.deny !== undefined) await say($, await whoIs($, e.agentId), `${text}  denied`, 'error', e.agentId ?? null)
    else if (hasFailed) await say($, await whoIs($, e.agentId), `${text}  ✗`, 'error', e.agentId ?? null)
    else if (isEdit) await say($, await whoIs($, e.agentId), text, 'info', e.agentId ?? null)
    if (isSettled || !didRun) await refreshStatus($, cfg)
    return ran
  })

  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    if (!e.parentAgentId) await noteMode($, e.permissionMode)
    if (started.deny !== undefined || !started.agentId) return started
    const id = started.agentId
    const card: AgentCard = {
      ...normalizeCard({}),
      id,
      type: e.name ?? e.subagentType,
      model: started.model,
      description: e.description,
      spawnedAt: await $.clock.now(),
      parentAgentId: e.parentAgentId ?? null,
    }
    await update($, agents, list => [...listOf<unknown>(list).map(normalizeCard), card])
    await safely($, async () => {
      await admit($, cfg.maxCards)
      await ensureSampler($)
    })
    await update($, loops, l => listOf<Loop>(l).filter(x => x.id !== id))
    await say($, shorten(cardTitle(card), LOG_WHO_MAX), `spawned · ${card.type}`, 'info', id)
    await refreshStatus($, cfg)
    return started
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    const id = e.agentId
    const now = await $.clock.now()
    await safely($, () => apply($, { kind: 'turn.complete', agentId: id ?? null, turnId: e.turnId, isAborted: e.isAborted, at: now }, deckOptions))
    if (!id) {
      const [t, a, cost] = await Promise.all([getTurn($), agentCounts($), costNow($)])
      const r = receiptOf(t, {
        durationMs: e.durationMs,
        agentsSince: a.total - t.agentsAtStart,
        costNow: cost,
        reason: e.reason,
      })
      await update($, receipt, () => r)
      await update($, main, m => ({ ...normalize(DEFAULT_MAIN, m), isRunning: false }))
      await refreshStatus($, cfg)
      return done
    }
    const cards = await getCards($)
    if (cards.some(c => c.id === id)) {
      const status = e.reason === 'answer' ? 'done' : e.reason === 'aborted' ? 'stopped' : 'failed'
      await update($, agents, list =>
        listOf<unknown>(list)
          .map(normalizeCard)
          .map(c => (c.id === id ? { ...c, status, endedAt: now, answer: shorten(e.answer, 400) } : c)),
      )
      const card = cards.find(c => c.id === id)
      const took = card ? fmtDuration(now - card.spawnedAt) : ''
      await say($, await whoIs($, id), status === 'done' ? `done · ${took}` : status, status === 'done' ? 'done' : 'error', id)
      await safely($, () => admit($, cfg.maxCards))
    } else {
      await update($, loops, l => listOf<Loop>(l).map(x => (x.id === id ? { ...x, isDone: true, lastAt: now } : x)))
    }
    await refreshStatus($, cfg)
    return done
  })

  on('turn.abort', async ($, e, next) => {
    const r = await next(e)
    await safely($, async () => apply($, { kind: 'abort', turnId: e.turnId, at: await $.clock.now() }, deckOptions))
    return r
  })

  // ---------------------------------------------------------------- drawing

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const [m, u, g, cards, lp, lines, t, r, v, now, deck] = await Promise.all([
      getMain($),
      getUsage($),
      getGate($),
      getCards($),
      getLoops($),
      getLog($),
      getTurn($),
      read($, receipt),
      getView($),
      $.clock.now(),
      getDeck($),
    ])
    // Re-arms the sampler after a hot reload dropped it; starting a timer writes no state.
    void safely($, () => ensureSampler($))
    return draw(
      {
        surface: e.surface,
        bodyColumns: e.props.bodyColumns,
        bodyRows: e.props.scroll?.bodyRows ?? e.viewport?.rows ?? 40,
        placement: e.props.placement,
        viewedAgentId: e.props.view?.agentId ?? null,
      },
      $.ui.resolve(e),
      { m, u, g, cards, lp, lines, t, r, v, now, deck },
      cfg,
      C,
      {
        toggleGate: async b => {
          await update($, view, x => ({ ...normalize(DEFAULT_VIEW, x), gateOpen: normalize(DEFAULT_VIEW, x).gateOpen === b ? null : b }))
        },
        toggleExpanded: async id => {
          await update($, view, x => ({ ...normalize(DEFAULT_VIEW, x), expanded: normalize(DEFAULT_VIEW, x).expanded === id ? null : id }))
        },
        select: async i => {
          const card = gridOrder(await getCards($))[i]
          if (card) await update($, view, x => ({ ...normalize(DEFAULT_VIEW, x), cursor: i, expanded: card.id }))
        },
        move: async delta => {
          const order = gridOrder(await getCards($))
          const n = order.length
          if (n === 0) return
          await update($, view, x => {
            const at = normalize(DEFAULT_VIEW, x).cursor
            const cursor = at === null ? 0 : (at + delta + n) % n
            return { ...normalize(DEFAULT_VIEW, x), cursor, expanded: order[cursor]?.id ?? null }
          })
        },
        clear: async () => {
          await update($, view, x => ({ ...normalize(DEFAULT_VIEW, x), cursor: null, expanded: null }))
        },
      },
    )
  })
}

files.hooks/core.ts:
// Pure data: defaults, reducers, formatting and layout math. Nothing here touches `$`, so every
// behaviour is testable directly (the test kit cannot raise a subagent's tool call or a
// permission check inside a call; these functions are what the hooks apply).
import type {
  AgentCard,
  Agents,
  AgentState,
  AgentTally,
  Aborts,
  Bucket,
  Cache,
  Check,
  Context,
  ContextSample,
  Gate,
  HotFiles,
  Layout,
  LogLine,
  Loop,
  Main,
  Prompt,
  Receipt,
  Tally,
  Tests,
  ToolNote,
  Tools,
  ToolStat,
  Turn,
  Usage,
  View,
} from '../types'

export const SCHEMA_VERSION = 3

// ---------------------------------------------------------------- defaults

export const DEFAULT_MAIN: Main = { model: '', effort: '', mode: '', steps: 0, isRunning: false }
export const DEFAULT_USAGE: Usage = {
  pct: null,
  tokens: null,
  window: 0,
  costUsd: null,
  limits: [],
  compactions: 0,
  lastCompactAt: null,
}
const ZERO: Tally = { rule: 0, ask: 0, cleared: 0, deny: 0 }
export const DEFAULT_GATE: Gate = { recent: [], totals: { file: ZERO, shell: ZERO, other: ZERO } }
export const DEFAULT_TURN: Turn = { edits: 0, errorStreak: 0, errors: 0, startedAt: 0, costAtStart: null, agentsAtStart: 0 }
export const DEFAULT_VIEW: View = { expanded: null, gateOpen: null, layout: null, cursor: null }

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)

/** A stored object merged over its defaults, so a value saved under an older shape still reads. */
export const normalize = <T extends object>(def: T, stored: unknown): T =>
  isObject(stored) ? ({ ...def, ...stored } as T) : def

/** A stored list, or empty when what is stored is not a list. */
export const listOf = <T>(stored: unknown): T[] => (Array.isArray(stored) ? (stored as T[]) : [])

export const normalizeGate = (stored: unknown): Gate => {
  const g = normalize(DEFAULT_GATE, stored)
  const totals = normalize(DEFAULT_GATE.totals, g.totals)
  return {
    recent: listOf<Check>(g.recent),
    totals: { file: normalize(ZERO, totals.file), shell: normalize(ZERO, totals.shell), other: normalize(ZERO, totals.other) },
  }
}

export const normalizeCard = (stored: unknown): AgentCard =>
  normalize<AgentCard>(
    {
      id: '',
      type: 'agent',
      model: '',
      description: '',
      status: 'running',
      spawnedAt: 0,
      endedAt: null,
      ctx: 0,
      out: 0,
      steps: 0,
      lastStop: null,
      tools: [],
      answer: '',
      parentAgentId: null,
    },
    stored,
  )

export const normalizeLog = (stored: unknown): LogLine[] =>
  listOf<Record<string, unknown>>(stored).map(l => ({
    at: typeof l.at === 'number' ? l.at : 0,
    who: String(l.who ?? ''),
    text: String(l.text ?? ''),
    agentId: typeof l.agentId === 'string' ? l.agentId : null,
    kind: l.kind === 'error' || l.kind === 'done' ? l.kind : 'info',
  }))

// ---------------------------------------------------------------- config

export type Panel = 'main' | 'prompt' | 'gate' | 'agents' | 'tools' | 'turn' | 'loops' | 'receipt' | 'log'
const PANELS: readonly Panel[] = ['main', 'prompt', 'gate', 'agents', 'tools', 'turn', 'loops', 'receipt', 'log']

export type Config = {
  panels: Panel[]
  motion: boolean
  maxCards: number
  layout: Layout
  palette: Palette
  openOnStart: boolean
  statusLine: boolean
  testPattern: RegExp
  isTestPatternFallback: boolean
  historyMinutes: number
  charts: boolean
}

export const GATE_LABEL = 'GATE'

// Flags stay 'i': a user pattern cannot add g or y, which would make .test stateful inside the pure reducer.
export const safeRegExp = (source: string, fallback: string): { re: RegExp; isFallback: boolean } => {
  try {
    return { re: new RegExp(source || fallback, 'i'), isFallback: false }
  } catch {
    return { re: new RegExp(fallback, 'i'), isFallback: true }
  }
}

/** The plugin's `/config` values, read leniently: anything malformed falls back to the default. */
export const parseConfig = (o: Readonly<Record<string, unknown>>): Config => {
  const str = (k: string, d: string) => (typeof o[k] === 'string' && o[k] !== '' ? (o[k] as string) : d)
  const bool = (k: string, d: boolean) => (typeof o[k] === 'boolean' ? (o[k] as boolean) : d)
  const panels = str('panels', PANELS.join(','))
    .split(',')
    .map(s => s.trim())
    .filter((p): p is Panel => (PANELS as readonly string[]).includes(p))
  const layout = str('layout', 'auto')
  const max = typeof o.maxCards === 'number' && Number.isFinite(o.maxCards) ? Math.round(o.maxCards) : MAX_CARDS
  const pattern = safeRegExp(str('testPattern', DEFAULT_TEST_PATTERN), DEFAULT_TEST_PATTERN)
  const minutes = typeof o.historyMinutes === 'number' && Number.isFinite(o.historyMinutes) ? Math.round(o.historyMinutes) : 30
  return {
    panels: panels.length > 0 ? [...new Set(panels)] : [...PANELS],
    motion: str('motion', 'while-active') !== 'off',
    maxCards: Math.min(200, Math.max(1, max)),
    layout: layout === 'compact' || layout === 'wide' || layout === 'mini' ? layout : 'auto',
    palette: oneOf(str('palette', 'theme'), ['theme', 'pastel', 'dracula'], 'theme'),
    openOnStart: bool('openOnStart', true),
    statusLine: bool('statusLine', true),
    testPattern: pattern.re,
    isTestPatternFallback: pattern.isFallback,
    historyMinutes: Math.min(30, Math.max(1, minutes)),
    charts: bool('charts', true),
  }
}

// ---------------------------------------------------------------- palette

export type Palette = 'theme' | 'pastel' | 'dracula'
export type Colors = Record<'main' | 'agent' | 'gate' | 'cleared' | 'amber' | 'warn' | 'dim' | 'faint' | 'text', string> & {
  /** Painted behind the whole deck; absent, the host's own background shows through. */
  bg?: string
}

/**
 * `theme` names the person's own theme colours (they follow light, dark and colour-blind themes);
 * `pastel` is fixed hex tuned for dark terminals.
 */
export const PALETTES: Record<Palette, Colors> = {
  theme: {
    main: 'claude',
    agent: 'suggestion',
    gate: 'success',
    cleared: 'permission',
    amber: 'warning',
    warn: 'error',
    dim: 'inactive',
    faint: 'subtle',
    text: 'text',
  },
  pastel: {
    main: '#7dd3fc',
    agent: '#93c5fd',
    gate: '#86efac',
    cleared: '#5eead4',
    amber: '#fcd34d',
    warn: '#fca5a5',
    dim: '#6b7280',
    faint: '#3f4654',
    text: '#e5e7eb',
    bg: '#111827',
  },
  dracula: {
    main: '#bd93f9',
    agent: '#8be9fd',
    gate: '#50fa7b',
    cleared: '#ff79c6',
    amber: '#ffb86c',
    warn: '#ff5555',
    dim: '#6272a4',
    faint: '#44475a',
    text: '#f8f8f2',
    bg: '#282a36',
  },
}

/** SVG cannot name theme keys: mid-tone colours that read on light and dark backgrounds. */
export const SVG_COLORS = { running: '#3b82f6', done: '#16a34a', failed: '#dc2626', other: '#8b5cf6', label: '#6b7280' }

// ---------------------------------------------------------------- formatting

/** `claude-opus-5-5` → `Opus 5.5`; anything else is shown as given. */
/**
 * A model id as people say it, from any provider's spelling: `claude-opus-5-5[1m]` → `Opus 5.5 1M`,
 * `us.anthropic.claude-sonnet-4-5-20250929-v1:0` → `Sonnet 4.5`, `claude-3-5-haiku-20241022` →
 * `Haiku 3.5`. Anything else is shown as given, cut to 22 characters.
 */
export const prettyModel = (id: string) => {
  if (!id) return '—'
  const cap = (f: string) => f.charAt(0).toUpperCase() + f.slice(1)
  const big = /\[1m\]|-1m\b/i.test(id) ? ' 1M' : ''
  const now = /claude-([a-z]+)-(\d+)(?:-(\d{1,2}))?(?:-\d{8})?(?![\d])/i.exec(id)
  if (now?.[1] && !/^\d/.test(now[1])) return `${cap(now[1].toLowerCase())} ${now[2]}${now[3] ? `.${now[3]}` : ''}${big}`
  const old = /claude-(\d+)(?:-(\d))?-([a-z]+)/i.exec(id)
  if (old?.[3]) return `${cap(old[3].toLowerCase())} ${old[1]}${old[2] ? `.${old[2]}` : ''}${big}`
  return shorten(id, 22)
}

/** Longest name a log line keeps; the log's name column grows to the longest one shown, up to this. */
export const LOG_WHO_MAX = 26

export const shorten = (s: string, n: number) => {
  const one = s.replace(/\s+/g, ' ').trim()
  return n <= 0 ? '' : one.length > n ? `${one.slice(0, Math.max(0, n - 1)).trimEnd()}…` : one
}

export const kTokens = (n: number) =>
  n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)}M` : n >= 1000 ? `${Math.round(n / 1000)}k` : String(n)

export const fmtDuration = (ms: number) => {
  const s = Math.max(0, Math.round(ms / 1000))
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  return m < 60 ? `${m}m${String(s % 60).padStart(2, '0')}s` : `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}m`
}

/** A running clock as the live cards draw it: m:ss, or XhYY past an hour. */
export const fmtTimer = (ms: number) => {
  const s = Math.max(0, Math.floor(ms / 1000))
  const m = Math.floor(s / 60)
  return m < 60 ? `${m}:${String(s % 60).padStart(2, '0')}` : `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}`
}

export const fmtClock = (ms: number) => (ms > 0 ? new Date(ms).toTimeString().slice(0, 8) : '--:--:--')

/** `1 error`, `2 errors`. */
export const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`

export const fmtUsd = (n: number) => (n >= 100 ? `$${Math.round(n)}` : `$${n.toFixed(2)}`)

/** A gauge of `width` cells: ▰ filled, ▱ empty. */
export const gauge = (pct: number, width: number) => {
  const full = Math.max(0, Math.min(width, Math.round((pct / 100) * width)))
  return { on: '▰'.repeat(full), off: '▱'.repeat(width - full) }
}

/** A rate-limit window's short name: `five_hour` → `5h`, `seven_day_opus` → `7d opus`. */
export const limitLabel = (kind: string) =>
  kind
    .replace(/five[_ -]?hours?/i, '5h')
    .replace(/seven[_ -]?days?/i, '7d')
    .replace(/[_-]+/g, ' ')
    .trim()

// ---------------------------------------------------------------- redaction

const SECRETS: [RegExp, string][] = [
  [/(authorization\s*[:=]\s*)(bearer\s+|basic\s+)?\S+/gi, '$1$2•••'],
  [/\b(bearer)\s+[A-Za-z0-9._~+/-]{8,}=*/gi, '$1 •••'],
  [/\b(sk|pk|rk|ghp|gho|ghs|github_pat|xox[abprs])[-_][A-Za-z0-9_-]{8,}/g, '•••'],
  [/((?:api[_-]?key|access[_-]?token|token|secret|password|passwd|pwd)\s*[=:]\s*)("[^"]*"|'[^']*'|\S+)/gi, '$1•••'],
  [/(--(?:token|password|api-key|secret)[= ])\S+/gi, '$1•••'],
  [/(\b[A-Z][A-Z0-9_]*(?:KEY|TOKEN|SECRET|PASSWORD)=)\S+/g, '$1•••'],
  [/(\b[a-z][a-z0-9+.-]*:\/\/[^\s/:@]+:)[^\s@]+@/gi, '$1•••@'],
]

/** What the gate drill-down may store: credentials masked before anything is written to state. */
export const redact = (s: string) => SECRETS.reduce((t, [re, to]) => t.replace(re, to), s)

// ---------------------------------------------------------------- tools and gate

const FILE_TOOLS = new Set(['Read', 'Edit', 'Write', 'NotebookEdit', 'Glob', 'Grep'])
const SHELL_TOOLS = new Set(['Bash', 'PowerShell'])
export const EDIT_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit'])

export const bucketOf = (tool: string): Bucket =>
  FILE_TOOLS.has(tool) ? 'file' : SHELL_TOOLS.has(tool) ? 'shell' : 'other'

/** One line saying what a call was about: its command, path or pattern; redacted. */
export const describeInput = (tool: string, input: unknown) => {
  const i = isObject(input) ? input : {}
  const path = typeof i.file_path === 'string' ? i.file_path.split(/[\\/]/).slice(-2).join('/') : ''
  const what =
    typeof i.command === 'string'
      ? i.command
      : path || (typeof i.pattern === 'string' ? i.pattern : typeof i.url === 'string' ? i.url : typeof i.description === 'string' ? i.description : '')
  return redact(what ? `${tool} → ${what}` : tool)
}

/** Keeps the last `max` checks, but never drops a pending ask: its settle must still find it. */
export const trimRecent = (list: Check[], max: number): Check[] => {
  let extra = list.length - max
  if (extra <= 0) return list
  const out: Check[] = []
  for (const c of list) {
    if (extra > 0 && c.verdict !== 'ask') {
      extra -= 1
      continue
    }
    out.push(c)
  }
  return out.slice(-max * 2)
}

export const recordCheck = (g: Gate, c: Check): Gate => {
  const t = g.totals[c.bucket]
  return {
    recent: trimRecent([...g.recent, c], 80),
    totals: { ...g.totals, [c.bucket]: { ...t, [c.verdict]: t[c.verdict] + 1 } },
  }
}

/** An `ask` settled by the call that followed it: it ran (cleared) or was refused (deny). */
export const settleCheck = (g: Gate, id: string, didRun: boolean): Gate => {
  const c = g.recent.find(r => r.id === id && r.verdict === 'ask')
  if (!c) return g
  const verdict = didRun ? 'cleared' : 'deny'
  const t = g.totals[c.bucket]
  return {
    recent: g.recent.map(r => (r === c ? { ...r, verdict } : r)),
    totals: { ...g.totals, [c.bucket]: { ...t, ask: Math.max(0, t.ask - 1), [verdict]: t[verdict] + 1 } },
  }
}

export const gateSummary = (g: Gate) => {
  const all = (['file', 'shell', 'other'] as const).reduce(
    (s, k) => ({
      rule: s.rule + g.totals[k].rule,
      ask: s.ask + g.totals[k].ask,
      cleared: s.cleared + g.totals[k].cleared,
      deny: s.deny + g.totals[k].deny,
    }),
    { ...ZERO },
  )
  return { ...all, total: all.rule + all.ask + all.cleared + all.deny }
}

// ---------------------------------------------------------------- turn

/**
 * The turn after one tool call. Errors count in the main loop only (a subagent's failure is its
 * own); edits count from every loop, so delegated work still counts.
 */
export const afterCall = (t: Turn, c: { inSubagent: boolean; hasFailed: boolean; isEdit: boolean }): Turn => ({
  ...t,
  errorStreak: c.inSubagent ? t.errorStreak : c.hasFailed ? t.errorStreak + 1 : 0,
  errors: t.errors + (!c.inSubagent && c.hasFailed ? 1 : 0),
  edits: t.edits + (c.isEdit ? 1 : 0),
})

export const receiptOf = (t: Turn, o: { durationMs: number; agentsSince: number; costNow: number | null; reason: string }): Receipt => ({
  durationMs: o.durationMs,
  agents: o.agentsSince,
  edits: t.edits,
  errors: t.errors,
  costDelta: o.costNow !== null && t.costAtStart !== null && o.costNow - t.costAtStart >= 0.005 ? o.costNow - t.costAtStart : null,
  reason: o.reason,
  startedAt: t.startedAt,
})

// ---------------------------------------------------------------- agents and loops

export type StepUsage = { input_tokens?: number; cache_read_input_tokens?: number; cache_creation_input_tokens?: number; output_tokens?: number } | null

/** A card after one of its model requests: its context is the latest step's whole input; output adds up. */
export const applyStep = (c: AgentCard, s: { model: string; usage: StepUsage; stopReason: string | null }): AgentCard => {
  const u = s.usage ?? {}
  const ctx = (u.input_tokens ?? 0) + (u.cache_read_input_tokens ?? 0) + (u.cache_creation_input_tokens ?? 0)
  return {
    ...c,
    model: c.model || s.model,
    steps: c.steps + 1,
    ctx: ctx > 0 ? ctx : c.ctx,
    out: c.out + (u.output_tokens ?? 0),
    lastStop: s.stopReason,
  }
}

export const noteTool = (c: AgentCard, n: ToolNote): AgentCard => ({ ...c, tools: [...c.tools, n].slice(-3) })

export const stepLoop = (loops: Loop[], id: string, at: number): Loop[] => {
  const found = loops.find(l => l.id === id)
  const next = found
    ? loops.map(l => (l === found ? { ...l, steps: l.steps + 1, lastAt: at } : l))
    : [...loops, { id, steps: 1, firstAt: at, lastAt: at, isDone: false }]
  return next.slice(-60)
}

export const LOOP_ACTIVE_MS = 15_000
export const isLoopActive = (l: Loop, now: number) => !l.isDone && now - l.lastAt < LOOP_ACTIVE_MS

/** Swimlane geometry: each agent's bar on one shared axis from the first spawn to now. */
export const lanes = (cards: AgentCard[], now: number, width: number) => {
  const start = Math.min(...cards.map(c => c.spawnedAt).filter(n => n > 0), now)
  const span = Math.max(1, now - start)
  return cards.map(c => {
    const from = Math.floor(((Math.max(c.spawnedAt, start) - start) / span) * width)
    const to = Math.max(from + 1, Math.ceil((((c.endedAt ?? now) - start) / span) * width))
    return { id: c.id, before: Math.min(from, width), bar: Math.min(to, width) - Math.min(from, width), after: width - Math.min(to, width) }
  })
}

// ---------------------------------------------------------------- layout

/** How many log lines fit: what the other panels leave, never fewer than 4 nor more than 8. */
export const logRows = (bodyRows: number, used: number) => Math.max(4, Math.min(8, bodyRows - used - 3))

/** Legend items that fit on one row of `width` cells, in order; the rest are dropped. */
export const fitLegend = <T extends { label: string }>(items: T[], width: number) => {
  const out: T[] = []
  let used = 0
  for (const it of items) {
    const w = it.label.length + 4
    if (used + w > width) break
    out.push(it)
    used += w
  }
  return out
}

export type TitlePart = { swatch?: { glyph: string; ch: string }; text: string; short: string }
export type FittedTitle = { sep: string; parts: TitlePart[] }

export const titleText = (f: FittedTitle) => f.parts.map(p => (p.swatch?.glyph ?? '') + p.text).join(f.sep)

/** Every part long or every part short, so a narrow title never loses its last count to truncation. */
export const fitTitle = (parts: TitlePart[], width: number): FittedTitle => {
  const long = { sep: ' · ', parts }
  if (titleText(long).length <= width) return long
  const spaced = { sep: ' ', parts: parts.map(p => ({ ...p, text: p.short })) }
  if (titleText(spaced).length <= width) return spaced
  return { sep: ' ', parts: parts.map(p => ({ ...p, text: p.swatch ? p.short.trimStart() : p.short })) }
}

/** A card's title row: the task in the agent's own words, the type only when there is none. */
export const cardTitle = (c: AgentCard) => c.description || c.type

/** A title split over two rows at a word boundary: `first` cells on row one, `rest` on row two. */
export const titleLines = (title: string, first: number, rest: number): [string, string] => {
  const t = title.replace(/\s+/g, ' ').trim()
  if (t.length <= first) return [t, '']
  const cut = t.lastIndexOf(' ', first)
  const at = cut > 0 ? cut : first
  return [t.slice(0, at).trim(), shorten(t.slice(at), rest)]
}

/**
 * What a turn's opening text was, for the log: the person's words, or for a turn the engine
 * opened with a tagged message (a subagent's hand-back, a task notification), that message's kind.
 */
const ENGINE_TAG = /^\s*<([a-z][\w-]*)/i

export const promptLine = (text: string): { who: string; text: string } => {
  const tag = ENGINE_TAG.exec(text)?.[1]
  if (!tag) return { who: 'you', text: shorten(text, 70) }
  const from = /\bfrom="([^"]+)"/.exec(text)?.[1]
  return { who: 'engine', text: shorten(`${tag.replace(/[-_]/g, ' ')}${from ? ` from ${from.slice(0, 8)}` : ''}`, 70) }
}

export const elapsedOf = (c: AgentCard, now: number) => (c.endedAt ?? now) - c.spawnedAt

// ---------------------------------------------------------------- deck

export const PROMPT_CHARS = 48
export const LATENCY_WINDOW = 20
export const ABORT_CAP = 20
export const SAMPLE_CAP = 180
export const SAMPLE_MS = 10_000
export const HOT_FILE_WARN = 4
export const TOOLS_SHOWN = 8
export const MAX_CARDS = 64
export const DEFAULT_TEST_PATTERN = '\\b(vitest|jest|pytest|go test|cargo test|npm test|pnpm test|bun test|mocha)\\b'
export const HOT_FILE_TOOLS: ReadonlySet<string> = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])

export type Deck = {
  prompt: Prompt
  cache: Cache
  tools: Tools
  hotFiles: HotFiles
  tests: Tests
  aborts: Aborts
  agents: Agents
  context: Context
}

export type DeckOptions = { testPattern: RegExp }

export type DeckEvent =
  | { kind: 'prompt'; text: string }
  | { kind: 'turn.start'; at: number; turnId: string; text: string }
  | { kind: 'step'; agentId: string | null; usage: StepUsage }
  | {
      kind: 'tool'
      tool: string
      agentId: string | null
      outcome: 'ok' | 'error' | 'denied'
      ms: number | null
      filePath: string | null
      command: string | null
      at: number
    }
  | { kind: 'turn.complete'; agentId: string | null; turnId: string; isAborted: boolean; at: number }
  | { kind: 'abort'; turnId: string; at: number }
  | { kind: 'measure'; percent: number | null; at: number }
  | { kind: 'compact'; at: number }
  | { kind: 'tick'; at: number; counts: Omit<AgentTally, 'spawning'> }
  | { kind: 'reset' }

type ToolEvent = Extract<DeckEvent, { kind: 'tool' }>

export const DEFAULT_PROMPT: Prompt = { text: '', startedAt: null, status: 'idle' }
export const DEFAULT_CACHE: Cache = { read: 0, input: 0, creation: 0 }
export const DEFAULT_TESTS: Tests = { light: 'off', pass: 0, fail: 0, lastAt: null }
export const DEFAULT_ABORTS: Aborts = { count: 0, at: [], turnIds: [] }
export const DEFAULT_AGENTS: Agents = { byType: {}, history: [] }
export const DEFAULT_CONTEXT: Context = { history: [], compactPending: false, lastPercent: null }
export const DEFAULT_DECK: Deck = {
  prompt: DEFAULT_PROMPT,
  cache: DEFAULT_CACHE,
  tools: {},
  hotFiles: {},
  tests: DEFAULT_TESTS,
  aborts: DEFAULT_ABORTS,
  agents: DEFAULT_AGENTS,
  context: DEFAULT_CONTEXT,
}
export const DEFAULT_OPTIONS: DeckOptions = { testPattern: new RegExp(DEFAULT_TEST_PATTERN, 'i') }

const DEFAULT_TOOL_STAT: ToolStat = { calls: 0, errors: 0, denies: 0, recentMs: [], recentOk: [], lastOk: true }
const ZERO_TALLY: AgentTally = { spawning: 0, running: 0, done: 0, error: 0 }

const recordOf = <T>(stored: unknown, each: (v: unknown) => T): Record<string, T> =>
  isObject(stored) ? Object.fromEntries(Object.entries(stored).map(([k, v]) => [k, each(v)])) : {}

const isNumber = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v)
const numberOr = (v: unknown, def: number): number => (isNumber(v) ? v : def)
const numberOrNull = (v: unknown): number | null => (isNumber(v) ? v : null)
const oneOf = <T extends string>(v: unknown, all: readonly T[], def: T): T => all.find(x => x === v) ?? def
const fieldsOf = (stored: unknown): Record<string, unknown> => (isObject(stored) ? stored : {})
const timed = (stored: unknown): Record<string, unknown>[] =>
  listOf<unknown>(stored).filter((v): v is Record<string, unknown> => isObject(v) && isNumber(v.at))

const PROMPT_STATUSES = ['idle', 'running', 'done', 'aborted'] as const
const TEST_LIGHTS = ['off', 'pass', 'fail'] as const

const normalizeToolStat = (stored: unknown): ToolStat => {
  const s = fieldsOf(stored)
  return {
    calls: numberOr(s.calls, 0),
    errors: numberOr(s.errors, 0),
    denies: numberOr(s.denies, 0),
    recentMs: listOf<unknown>(s.recentMs).filter(isNumber),
    recentOk: listOf<unknown>(s.recentOk).filter((v): v is boolean => typeof v === 'boolean'),
    lastOk: typeof s.lastOk === 'boolean' ? s.lastOk : true,
  }
}

const normalizeTally = (stored: unknown): AgentTally => {
  const t = fieldsOf(stored)
  return { spawning: numberOr(t.spawning, 0), running: numberOr(t.running, 0), done: numberOr(t.done, 0), error: numberOr(t.error, 0) }
}

/** Every field coerced to its type, so no corrupt stored value can throw in a reducer or a render. */
export const normalizeDeck = (stored: Partial<Record<keyof Deck, unknown>>): Deck => {
  const p = fieldsOf(stored.prompt)
  const c = fieldsOf(stored.cache)
  const t = fieldsOf(stored.tests)
  const a = fieldsOf(stored.aborts)
  const ag = fieldsOf(stored.agents)
  const cx = fieldsOf(stored.context)
  return {
    prompt: {
      text: typeof p.text === 'string' ? p.text : '',
      startedAt: numberOrNull(p.startedAt),
      status: oneOf(p.status, PROMPT_STATUSES, 'idle'),
    },
    cache: { read: numberOr(c.read, 0), input: numberOr(c.input, 0), creation: numberOr(c.creation, 0) },
    tools: recordOf(stored.tools, normalizeToolStat),
    hotFiles: recordOf(stored.hotFiles, v => numberOr(v, 0)),
    tests: { light: oneOf(t.light, TEST_LIGHTS, 'off'), pass: numberOr(t.pass, 0), fail: numberOr(t.fail, 0), lastAt: numberOrNull(t.lastAt) },
    aborts: {
      count: numberOr(a.count, 0),
      at: listOf<unknown>(a.at).filter(isNumber),
      turnIds: listOf<unknown>(a.turnIds).filter((v): v is string => typeof v === 'string'),
    },
    agents: {
      byType: recordOf(ag.byType, normalizeTally),
      history: timed(ag.history).map(h => ({ at: numberOr(h.at, 0), running: numberOr(h.running, 0), done: numberOr(h.done, 0), error: numberOr(h.error, 0) })),
    },
    context: {
      history: timed(cx.history).map(h => ({
        at: numberOr(h.at, 0),
        percent: numberOr(h.percent, 0),
        cacheHit: numberOr(h.cacheHit, 0),
        compacted: h.compacted === true,
      })),
      compactPending: cx.compactPending === true,
      lastPercent: numberOrNull(cx.lastPercent),
    },
  }
}

const capped = <T>(list: T[], item: T, cap: number): T[] => [...list, item].slice(-cap)

const noteAbort = (a: Aborts, turnId: string, at: number): Aborts =>
  a.turnIds.includes(turnId)
    ? a
    : { count: a.count + 1, at: capped(a.at, at, ABORT_CAP), turnIds: capped(a.turnIds, turnId, ABORT_CAP) }

const recordTool = (s: ToolStat, e: ToolEvent): ToolStat => ({
  calls: s.calls + 1,
  errors: s.errors + (e.outcome === 'error' ? 1 : 0),
  denies: s.denies + (e.outcome === 'denied' ? 1 : 0),
  recentMs: e.ms !== null && e.outcome !== 'denied' ? capped(s.recentMs, e.ms, LATENCY_WINDOW) : s.recentMs,
  recentOk: capped(s.recentOk, e.outcome === 'ok', LATENCY_WINDOW),
  lastOk: e.outcome === 'ok',
})

const recordEdit = (h: HotFiles, e: ToolEvent): HotFiles =>
  HOT_FILE_TOOLS.has(e.tool) && e.outcome !== 'denied' && e.filePath !== null
    ? { ...h, [e.filePath]: (h[e.filePath] ?? 0) + 1 }
    : h

const recordTest = (t: Tests, e: ToolEvent, pattern: RegExp): Tests => {
  if (e.tool !== 'Bash' || e.outcome === 'denied' || e.command === null || !pattern.test(e.command)) return t
  return e.outcome === 'ok'
    ? { light: 'pass', pass: t.pass + 1, fail: t.fail, lastAt: e.at }
    : { light: 'fail', pass: t.pass, fail: t.fail + 1, lastAt: e.at }
}

/** A sample that coalesces into the previous one keeps that one's compaction mark. */
const sampleContext = (c: Context, s: ContextSample, coalesce: boolean): Context => {
  const last = c.history.at(-1)
  const history =
    coalesce && last && s.at - last.at < SAMPLE_MS
      ? [...c.history.slice(0, -1), { ...s, compacted: s.compacted || last.compacted }]
      : capped(c.history, s, SAMPLE_CAP)
  return { history, compactPending: false, lastPercent: s.percent }
}

export const reduceDeck = (d: Deck, e: DeckEvent, opts: DeckOptions = DEFAULT_OPTIONS): Deck => {
  switch (e.kind) {
    case 'prompt':
      return { ...d, prompt: { ...d.prompt, text: shorten(redact(e.text), PROMPT_CHARS) } }
    case 'turn.start': {
      // A plugin beneath can abort the turn inside its own start, before this event is applied.
      const status = d.aborts.turnIds.includes(e.turnId) ? 'aborted' : 'running'
      // A turn an engine message opened (a task notification, a hand-back) keeps the human's prompt.
      const isHuman = e.text.trim() !== '' && !ENGINE_TAG.test(e.text)
      const text = isHuman ? shorten(redact(e.text), PROMPT_CHARS) : d.prompt.text
      return { ...d, prompt: { text, status, startedAt: e.at }, hotFiles: {} }
    }
    case 'step': {
      if (e.agentId !== null) return d
      const u = e.usage ?? {}
      return {
        ...d,
        cache: {
          read: d.cache.read + (u.cache_read_input_tokens ?? 0),
          input: d.cache.input + (u.input_tokens ?? 0),
          creation: d.cache.creation + (u.cache_creation_input_tokens ?? 0),
        },
      }
    }
    case 'tool':
      return {
        ...d,
        tools: { ...d.tools, [e.tool]: recordTool(d.tools[e.tool] ?? DEFAULT_TOOL_STAT, e) },
        hotFiles: recordEdit(d.hotFiles, e),
        tests: recordTest(d.tests, e, opts.testPattern),
      }
    case 'turn.complete': {
      if (e.agentId !== null) return d
      const isAborted = e.isAborted || d.prompt.status === 'aborted'
      return {
        ...d,
        prompt: { ...d.prompt, status: isAborted ? 'aborted' : 'done' },
        aborts: isAborted ? noteAbort(d.aborts, e.turnId, e.at) : d.aborts,
      }
    }
    case 'abort':
      return { ...d, prompt: { ...d.prompt, status: 'aborted' }, aborts: noteAbort(d.aborts, e.turnId, e.at) }
    case 'measure':
      if (e.percent === null) return d
      return {
        ...d,
        context: sampleContext(d.context, { at: e.at, percent: e.percent, cacheHit: cacheHit(d.cache), compacted: d.context.compactPending }, true),
      }
    case 'compact':
      return d.context.compactPending ? d : { ...d, context: { ...d.context, compactPending: true } }
    case 'tick': {
      const { running, done, error } = e.counts
      const p = d.context.lastPercent
      return {
        ...d,
        agents: { ...d.agents, history: capped(d.agents.history, { at: e.at, running, done, error }, SAMPLE_CAP) },
        context:
          p === null
            ? d.context
            : sampleContext(d.context, { at: e.at, percent: p, cacheHit: cacheHit(d.cache), compacted: d.context.compactPending }, false),
      }
    }
    case 'reset':
      return DEFAULT_DECK
    default:
      return d
  }
}

export const cacheHit = (c: Cache): number => {
  const sum = c.read + c.input + c.creation
  return sum === 0 ? 0 : c.read / sum
}

export const meanMs = (s: ToolStat): number | null =>
  s.recentMs.length === 0 ? null : s.recentMs.reduce((a, b) => a + b, 0) / s.recentMs.length

export const badDots = (s: ToolStat): number => Math.min(4, s.recentOk.filter(ok => !ok).length)

export const topTools = (t: Tools, n: number = TOOLS_SHOWN): [string, ToolStat][] =>
  Object.entries(t)
    .sort(([a, x], [b, y]) => y.calls - x.calls || (a < b ? -1 : a > b ? 1 : 0))
    .slice(0, n)

export const toolName = (tool: string): string => (tool.startsWith('mcp__') ? (tool.split('__').at(-1) ?? tool) : tool)

export const hotFile = (h: HotFiles): { path: string; edits: number } | null =>
  Object.entries(h).reduce<{ path: string; edits: number } | null>(
    (best, [path, edits]) => (!best || edits > best.edits || (edits === best.edits && path < best.path) ? { path, edits } : best),
    null,
  )

export const stateOf = (c: AgentCard): AgentState => {
  if (c.status === 'failed' || c.status === 'stopped') return 'error'
  if (c.status === 'done') return 'done'
  if (c.status !== 'running') return 'running'
  if (c.steps === 0) return 'spawning'
  return c.tools.at(-1)?.isError ? 'error' : 'running'
}

export const laneOf = (c: AgentCard): string => {
  if (c.type !== '' && c.type !== 'teammate') return c.type
  return c.description.trim().split(/\s+/)[0] || 'other'
}

const addTally = (t: AgentTally, s: AgentState): AgentTally => ({ ...t, [s]: t[s] + 1 })

export const tallyByType = (cards: AgentCard[], folded: Record<string, AgentTally>): Record<string, AgentTally> =>
  cards.reduce<Record<string, AgentTally>>((out, c) => {
    const lane = laneOf(c)
    return { ...out, [lane]: addTally(out[lane] ?? ZERO_TALLY, stateOf(c)) }
  }, folded)

export const totals = (byType: Record<string, AgentTally>): AgentTally =>
  Object.values(byType).reduce(
    (a, t) => ({ spawning: a.spawning + t.spawning, running: a.running + t.running, done: a.done + t.done, error: a.error + t.error }),
    ZERO_TALLY,
  )

export const admitCards = (
  cards: AgentCard[],
  folded: Record<string, AgentTally>,
  cap: number,
): { cards: AgentCard[]; folded: Record<string, AgentTally> } => {
  const extra = cards.length - cap
  if (extra <= 0) return { cards, folded }
  const dropped = new Set(
    cards
      .filter(c => {
        const s = stateOf(c)
        return s === 'done' || s === 'error'
      })
      .sort((a, b) => a.spawnedAt - b.spawnedAt)
      .slice(0, extra),
  )
  if (dropped.size === 0) return { cards, folded }
  return { cards: cards.filter(c => !dropped.has(c)), folded: tallyByType([...dropped], folded) }
}

export const gridOrder = (cards: AgentCard[]): AgentCard[] => {
  const count = new Map<string, number>()
  for (const c of cards) count.set(laneOf(c), (count.get(laneOf(c)) ?? 0) + 1)
  return [...cards].sort((a, b) => {
    const la = laneOf(a)
    const lb = laneOf(b)
    return (count.get(lb) ?? 0) - (count.get(la) ?? 0) || (la < lb ? -1 : la > lb ? 1 : 0) || a.spawnedAt - b.spawnedAt
  })
}

export const isSampling = (p: Prompt, cards: AgentCard[]): boolean =>
  p.status === 'running' ||
  cards.some(c => {
    const s = stateOf(c)
    return s === 'spawning' || s === 'running'
  })

