import type { Elements, RenderElement, RenderSurface } from 'claude-code'

import type { AgentCard, Bucket, Check, Gate, Layout, LogLine, Loop, Main, Receipt, Turn, Usage, View } from '../types'
import { bandPanels, bandTitles, chartColors, titleColumns, windowMinutes, type BandPanel, type ChartInput } from './charts'
import {
  LOG_WHO_MAX,
  GATE_LABEL,
  HOT_FILE_WARN,
  SVG_COLORS,
  badDots,
  cacheHit,
  cardTitle,
  fitLegend,
  fitTitle,
  fmtClock,
  fmtDuration,
  fmtTimer,
  fmtUsd,
  gateSummary,
  gauge,
  gridOrder,
  hotFile,
  isLoopActive,
  kTokens,
  laneOf,
  lanes,
  limitLabel,
  logRows,
  meanMs,
  plural,
  prettyModel,
  shorten,
  stateOf,
  tallyByType,
  titleLines,
  toolName,
  topTools,
  totals,
} from './core'
import type { Colors, Config, Deck, Panel } from './core'
import { encodeCells, type Palette as RasterPalette } from './raster'
import { CELL_PX, GAUGE_HEIGHT, gaugeSvg, gaugeWidth, gridSvg, hex } from './svg'

export type PaneView = { surface: RenderSurface; bodyColumns: number; bodyRows: number; placement: 'dock' | 'inline'; viewedAgentId: string | null }
export type DrawData = { m: Main; u: Usage; g: Gate; cards: AgentCard[]; lp: Loop[]; lines: LogLine[]; t: Turn; r: Receipt | null; v: View; now: number; deck: Deck }
export type Actions = {
  toggleGate: (b: Bucket) => Promise<void>
  toggleExpanded: (id: string) => Promise<void>
  select: (i: number) => Promise<void>
  move: (delta: 1 | -1) => Promise<void>
  clear: () => Promise<void>
}

/** The terminal draws the band as Raster, the desktop as Svg; inline above the prompt the pane has no rows to spare. */
export const bandRows = (p: { surface: RenderSurface; placement: 'dock' | 'inline'; layout: Layout; columns: number; rows: number; charts: boolean }): 0 | 4 | 6 =>
  (p.surface !== 'terminal' && p.surface !== 'desktop') || p.placement !== 'dock' || p.layout === 'mini' || p.columns < 60 || p.rows < 15 || !p.charts ? 0 : p.rows >= 30 ? 6 : 4

const lastSegments = (path: string) => path.split('/').filter(Boolean).slice(-2).join('/')
const sumTotals = (t: { rule: number; ask: number; cleared: number; deny: number }) => t.rule + t.ask + t.cleared + t.deny
const chartHex = (colors: RasterPalette, ch: string) => hex(colors[ch] ?? 0)

export const draw = (pv: PaneView, els: Elements[RenderSurface], d: DrawData, cfg: Config, C: Colors, act: Actions): RenderElement => {
  const { Box, Text, Button } = els
  const hasClient = 'Client' in els
  const { m, u, g, cards, lp, lines, t, r, v, now, deck } = d
  const W = Math.max(40, pv.bodyColumns)
  const layout = v.layout ?? cfg.layout
  const isWide = layout === 'wide' || (layout === 'auto' && W >= 110)
  const colW = isWide ? Math.floor((W - 2) / 2) : W
  const modelName = prettyModel(m.model)
  const viewed = pv.viewedAgentId
  const running = cards.filter(c => c.status === 'running')
  const motion = cfg.motion && hasClient
  const s = gateSummary(g)
  const order = gridOrder(cards)
  const tally = totals(tallyByType(cards, deck.agents.byType))
  const hot = hotFile(deck.hotFiles)
  const top = topTools(deck.tools)
  const hasCache = deck.cache.read + deck.cache.input + deck.cache.creation > 0
  const cachePct = Math.round(cacheHit(deck.cache) * 100)
  const promptStatus =
    s.ask > 0
      ? `waiting on you: ${plural(s.ask, 'permission ask')}`
      : deck.prompt.status === 'idle'
        ? 'waiting on you'
        : deck.prompt.status
  const testsWord = deck.tests.light === 'pass' ? `PASS ${deck.tests.pass}` : deck.tests.light === 'fail' ? `FAIL ${deck.tests.fail}` : null
  const Raster = 'Raster' in els ? els.Raster : null
  const Svg = pv.surface !== 'terminal' && 'Svg' in els ? els.Svg : null
  // The desktop paints Text in a proportional font over a grid measured in code-font cells (ADR 0005).
  const isDesktop = pv.surface === 'desktop'
  const DesktopSvg = isDesktop ? Svg : null
  const chartPalette = chartColors(cfg.palette)
  const nBand = Raster || DesktopSvg ? bandRows({ surface: pv.surface, placement: pv.placement, layout, columns: pv.bodyColumns, rows: pv.bodyRows, charts: cfg.charts }) : 0
  const chartInput: ChartInput = { context: deck.context.history, history: deck.agents.history, cards, cursor: v.cursor, now, minutes: cfg.historyMinutes }
  const band = nBand > 0 ? bandPanels(chartInput, pv.bodyColumns, nBand * 2) : null
  const bandCost = band ? nBand + 3 : 0
  // A panel with nothing to show yet takes no room: most sessions never spawn an agent.
  const isEmpty: Record<Panel, boolean> = {
    main: false,
    prompt: deck.prompt.status === 'idle' && deck.prompt.text === '',
    gate: g.recent.length === 0 && s.total === 0,
    agents: cards.length === 0,
    tools: top.length === 0,
    turn: !testsWord && !hot && deck.aborts.count === 0 && s.total === 0,
    loops: lp.length === 0,
    receipt: !m.isRunning && !r,
    log: false,
  }
  const panels = cfg.panels.filter(q => !isEmpty[q])
  const decider = m.mode === 'auto' ? 'classifier' : 'you'

  // A connector between panels: animated while its flow is live, a dim line otherwise.
  const rail = (key: string, active: boolean, color: string, width: number, marks: number[] = [], isMerge = false) =>
    motion ? (
      <els.Client
        key={key}
        module="./rail.tsx"
        width={width}
        height={1}
        props={{ active, width, color, dim: C.faint, marks, isMerge }}
      />
    ) : (
      <Text color={C.faint}>{'─'.repeat(Math.max(1, width))}</Text>
    )

  // A start time of 0 is unknown (state saved before it was recorded): no clock, not decades.
  const clock = (key: string, since: number, endAt: number | null, color: string) =>
    since <= 0 ? (
      <Text color={color}>—</Text>
    ) : hasClient ? (
      <els.Client key={key} module="./elapsed.tsx" props={{ since, now, endAt, color }} />
    ) : (
      <Text color={color}>{fmtTimer((endAt ?? now) - since)}</Text>
    )

  // ---- main
  const effortN = { low: 1, medium: 2, high: 3, xhigh: 4, max: 4 }[m.effort] ?? 0
  const effortGauge = { on: '▮'.repeat(effortN), off: '▯'.repeat(4 - effortN) }
  const ctxGauge = u.pct !== null ? gauge(u.pct, 10) : null
  const gaugeSvgOf = (Svg: NonNullable<typeof DesktopSvg>, g: { on: string; off: string }, isWarn: boolean, alt: string) => (
    <Svg source={gaugeSvg(g, chartHex(chartPalette, isWarn ? 'e' : 'c'), chartHex(chartPalette, 's'))} alt={alt} width={gaugeWidth(g)} height={GAUGE_HEIGHT} />
  )
  // Each phrase is its own Text in a wrapping row, so a row too wide for the proportional font breaks between phrases.
  const desktopMainRows = (Svg: NonNullable<typeof DesktopSvg>) => [
    <Box flexWrap="wrap" columnGap={2}>
      <Box columnGap={1} alignItems="center">
        <Text dimColor>effort</Text>
        {gaugeSvgOf(Svg, effortGauge, false, `effort ${m.effort || '—'}`)}
        <Text color={C.main} bold>
          {m.effort || '—'}
        </Text>
      </Box>
      {m.mode ? <Text dimColor>{`mode ${m.mode}`}</Text> : null}
      <Text dimColor>{`${m.steps} req`}</Text>
    </Box>,
    ctxGauge ? (
      <Box flexWrap="wrap" columnGap={2}>
        <Box columnGap={1} alignItems="center">
          <Text dimColor>ctx</Text>
          {gaugeSvgOf(Svg, ctxGauge, (u.pct ?? 0) >= 80, `context ${Math.round(u.pct ?? 0)}%`)}
          <Text bold>{`${Math.round(u.pct ?? 0)}%`}</Text>
        </Box>
        {u.tokens !== null ? <Text dimColor>{`${kTokens(u.tokens)}/${kTokens(u.window)}`}</Text> : null}
        {u.compactions > 0 ? <Text color={C.amber}>{`⟲${u.compactions}`}</Text> : null}
        {hasCache ? <Text dimColor>{`cache hit ${cachePct}%`}</Text> : null}
      </Box>
    ) : null,
    u.costUsd !== null || u.limits.length > 0 ? (
      <Box flexWrap="wrap" columnGap={2}>
        {u.costUsd !== null ? <Text color={C.text}>{fmtUsd(u.costUsd)}</Text> : null}
        {u.limits.slice(0, 2).map(l => (
          <Box columnGap={1} alignItems="center">
            <Text dimColor>{limitLabel(l.kind)}</Text>
            {gaugeSvgOf(Svg, gauge(l.pct, 5), l.pct >= 80, `${limitLabel(l.kind)} ${Math.round(l.pct)}%`)}
            <Text dimColor>{`${Math.round(l.pct)}%`}</Text>
          </Box>
        ))}
      </Box>
    ) : null,
  ]
  const terminalMainRows = () => [
    <Text wrap="truncate">
      <Text dimColor>effort </Text>
      <Text color={C.main}>{effortGauge.on + effortGauge.off} </Text>
      <Text color={C.main} bold>
        {m.effort || '—'}
      </Text>
      {m.mode ? <Text dimColor>{`   mode ${m.mode}`}</Text> : null}
      <Text dimColor>{`   ${m.steps} req`}</Text>
    </Text>,
    ctxGauge ? (
      <Text wrap="truncate">
        <Text dimColor>ctx </Text>
        <Text color={u.pct !== null && u.pct >= 80 ? C.warn : C.main}>{ctxGauge.on}</Text>
        <Text color={C.faint}>{ctxGauge.off}</Text>
        <Text bold>{` ${Math.round(u.pct ?? 0)}%`}</Text>
        {u.tokens !== null ? <Text dimColor>{` ${kTokens(u.tokens)}/${kTokens(u.window)}`}</Text> : null}
        {u.compactions > 0 ? <Text color={C.amber}>{`  ⟲${u.compactions}`}</Text> : null}
        {hasCache ? <Text dimColor>{`  cache hit ${cachePct}%`}</Text> : null}
      </Text>
    ) : null,
    u.costUsd !== null || u.limits.length > 0 ? (
      <Text wrap="truncate">
        {u.costUsd !== null ? <Text color={C.text}>{`${fmtUsd(u.costUsd)}   `}</Text> : null}
        {u.limits.slice(0, 2).map(l => {
          const lg = gauge(l.pct, 5)
          return (
            <Text wrap="truncate">
              <Text dimColor>{`${limitLabel(l.kind)} `}</Text>
              <Text color={l.pct >= 80 ? C.warn : C.main}>{lg.on}</Text>
              <Text color={C.faint}>{lg.off}</Text>
              <Text dimColor>{` ${Math.round(l.pct)}%  `}</Text>
            </Text>
          )
        })}
      </Text>
    ) : null,
  ]
  const mainPanel = (w: number) => (
    <Box flexDirection="column" borderStyle="round" borderColor={C.main} paddingX={1} width={w}>
      <Box justifyContent="space-between">
        <Text color={C.main} bold>
          {modelName} · main
        </Text>
        <Text color={m.isRunning ? C.main : C.dim}>{m.isRunning ? '● working' : '○ idle'}</Text>
      </Box>
      {DesktopSvg ? desktopMainRows(DesktopSvg) : terminalMainRows()}
    </Box>
  )

  // ---- prompt: the turn in flight, and whether it waits on you
  const promptStart = deck.prompt.startedAt ?? 0
  // Between an abort and the main turn.complete, the receipt still belongs to the turn before.
  const isOwnReceipt = r !== null && promptStart > 0 && (r.startedAt ?? 0) >= promptStart
  const promptEnd = deck.prompt.status === 'running' ? null : isOwnReceipt ? promptStart + r.durationMs : now
  // The stored prompt is already short (48 characters), so the desktop wraps it whole instead of cutting it to the row.
  const promptPanel = (w: number) =>
    isDesktop ? (
      <Box width={w} flexWrap="wrap" columnGap={1}>
        <Text bold>PROMPT</Text>
        <Text wrap="wrap">{`"${deck.prompt.text}"`}</Text>
        <Box flexShrink={0}>{clock('prompt-clock', promptStart, promptEnd, C.dim)}</Box>
        <Text color={s.ask > 0 ? C.amber : C.dim} wrap="wrap">{`· ${promptStatus}`}</Text>
      </Box>
    ) : (
      <Box width={w}>
        <Text wrap="truncate">
          <Text bold>PROMPT  </Text>
          <Text>{`"${shorten(deck.prompt.text, Math.max(8, w - promptStatus.length - 22))}" `}</Text>
        </Text>
        <Box flexShrink={0}>{clock('prompt-clock', promptStart, promptEnd, C.dim)}</Box>
        <Text color={s.ask > 0 ? C.amber : C.dim} wrap="truncate">{` · ${promptStatus}`}</Text>
      </Box>
    )

  // ---- gate
  const verdictColor = (c: Check) =>
    c.verdict === 'rule' ? C.gate : c.verdict === 'cleared' ? C.cleared : c.verdict === 'ask' ? C.amber : C.warn
  const gatePanel = (w: number) => {
    const strip = g.recent.slice(-Math.max(8, w - 4))
    const open = v.gateOpen
    return (
      <Box flexDirection="column" borderStyle="round" borderColor={C.gate} paddingX={1} width={w}>
        <Box justifyContent="space-between">
          <Text color={C.gate} bold>
            {GATE_LABEL} · permissions
          </Text>
          <Text dimColor>{`${s.total} checks`}</Text>
        </Box>
        <Box>
          {strip.length === 0 ? <Text color={C.faint}>no checks yet</Text> : null}
          {strip.map(c => (
            <Text color={verdictColor(c)} dimColor={c.inSubagent}>
              {c.verdict === 'deny' ? '✗' : '■'}
            </Text>
          ))}
        </Box>
        <Text wrap="truncate">
          <Text color={C.gate}>■</Text>
          <Text dimColor>{` ${s.rule} allowed  `}</Text>
          <Text color={C.cleared}>■</Text>
          <Text dimColor>{` ${s.cleared} ${decider}  `}</Text>
          {s.ask > 0 ? <Text color={C.amber}>{`■ ${s.ask} pending  `}</Text> : null}
          <Text color={s.deny > 0 ? C.warn : C.dim}>{`✗ ${s.deny} denied`}</Text>
          {w >= 80 && g.recent.some(c => c.inSubagent) ? <Text color={C.faint}>{'  dim: in subagents'}</Text> : null}
        </Text>
        <Box columnGap={2}>
          {(['file', 'shell', 'other'] as const).map((b: Bucket) => {
            const tl = g.totals[b]
            const n = tl.rule + tl.ask + tl.cleared + tl.deny
            return (
              <Button
                key={`gate-${b}`}
                plain
                hotkey={b[0]}
                label={`${b} ${n}${open === b ? ' ▾' : ''}`}
                dimColor={n === 0}
                onPress={() => act.toggleGate(b)}
              />
            )
          })}
        </Box>
        {open
          ? g.recent
              .filter(c => c.bucket === open)
              .slice(-5)
              .map(c => (
                <Text wrap="truncate">
                  <Text color={verdictColor(c)}>{c.verdict === 'deny' ? '✗ ' : '■ '}</Text>
                  <Text color={C.dim}>{`${(c.verdict === 'rule' ? 'allowed' : c.verdict === 'cleared' ? decider : c.verdict === 'ask' ? 'pending' : 'denied').padEnd(10)} `}</Text>
                  <Text dimColor={c.inSubagent}>{shorten(c.detail, Math.max(10, w - 18))}</Text>
                </Text>
              ))
          : null}
      </Box>
    )
  }

  // ---- agents: cards up to the limit, swimlanes beyond it
  const statusColor = (c: AgentCard) => (c.status === 'failed' ? C.warn : c.status === 'done' ? C.gate : C.agent)
  const glyph = (c: AgentCard) => (c.status === 'running' ? '◐' : c.status === 'done' ? '✓' : c.status === 'failed' ? '✗' : '■')
  const expandOnPress = (id: string) => () => act.toggleExpanded(id)

  // Cards need 20 columns each; more agents than fit side by side switch to lanes.
  const fitCards = (w: number) => Math.max(1, Math.floor((w + 1) / 21))

  // Nine numbered entries share one row; below 12 columns each, a label is its number and a state glyph.
  const STATE_GLYPH = { spawning: '·', running: '●', done: '✓', error: '✗' } as const
  const stateColor = { spawning: C.dim, running: C.agent, done: C.gate, error: C.warn } as const
  const numbered = (w: number) => {
    const first = order.slice(0, 9)
    const per = Math.floor((w - (first.length - 1)) / first.length)
    return (
      <Box columnGap={1} width={w} overflow="hidden">
        {first.map((c, i) => {
          const state = stateOf(c)
          const dim = v.cursor !== null && v.cursor !== i
          const onPress = () => act.select(i)
          return per >= 12 ? (
            <Button key={`agent-${i}`} plain hotkey={String(i + 1)} label={shorten(`${i + 1} ${laneOf(c)} ${kTokens(c.ctx)} ${state}`, per)} dimColor={dim} onPress={onPress} />
          ) : (
            <Box>
              <Button key={`agent-${i}`} plain hotkey={String(i + 1)} label={String(i + 1)} dimColor={dim} onPress={onPress} />
              <Text color={stateColor[state]}>{STATE_GLYPH[state]}</Text>
            </Box>
          )
        })}
      </Box>
    )
  }
  const cursorCard = v.cursor !== null ? order[v.cursor] : undefined
  const hasNav = cards.length > 9
  const hasClear = v.cursor !== null || v.expanded !== null
  const dropped = band?.dropped ?? 0
  const hasCursorRow = cards.length > 0 && (hasNav || hasClear || cursorCard !== undefined)
  const cursorRow = (w: number) => (
    <Box columnGap={2} width={w}>
      {hasNav ? <Button key="cursor-next" plain hotkey="n" label="n next" onPress={() => act.move(1)} /> : null}
      {hasNav ? <Button key="cursor-back" plain hotkey="b" label="b back" onPress={() => act.move(-1)} /> : null}
      {hasClear ? <Button key="cursor-clear" plain hotkey="x" label="x clear" onPress={() => act.clear()} /> : null}
      {cursorCard ? (
        <Text color={C.amber} wrap="truncate">
          {`cursor ▸ #${cursorCard.id.slice(0, 6)} ${cursorCard.type} ${kTokens(cursorCard.ctx)} ${toolName(cursorCard.tools.at(-1)?.tool ?? '')}`.trimEnd()}
        </Text>
      ) : null}
    </Box>
  )

  const agentsPanel = (w: number) => {
    const fit = fitCards(w)
    const useLanes = cards.length > fit
    const header = (
      <Box flexDirection="column" width={w}>
        <Box justifyContent="space-between" width={w}>
          <Text bold>{`agents · ${tally.spawning + tally.running} running · ${tally.spawning + tally.running + tally.done + tally.error} total`}</Text>
          {cards.length > 0 ? <Text color={C.faint}>1-{Math.min(cards.length, 9)} select</Text> : null}
        </Box>
        {cards.length > 0 ? numbered(w) : null}
        {hasCursorRow ? cursorRow(w) : null}
      </Box>
    )
    if (cards.length === 0) {
      return (
        <Box flexDirection="column" width={w}>
          {header}
          <Text color={C.faint}>no subagents yet</Text>
        </Box>
      )
    }
    if (useLanes) {
      const shown = cards.slice(-6)
      const barW = Math.max(8, w - 28)
      const geo = lanes(shown, now, barW)
      return (
        <Box flexDirection="column" width={w}>
          {header}
          {cards.length > shown.length ? <Text color={C.faint}>{`+${cards.length - shown.length} earlier`}</Text> : null}
          {shown.map((c, i) => {
            const gm = geo[i]
            const isViewed = viewed === c.id
            return (
              <Box>
                <Text color={statusColor(c)} bold={isViewed}>{`${isViewed ? '▶' : glyph(c)} `}</Text>
                <Box width={17}>
                  <Button key={`card-${c.id}`} plain label={shorten(cardTitle(c), 14)} onPress={expandOnPress(c.id)} />
                </Box>
                <Text color={C.faint}>{' ' + '·'.repeat(gm?.before ?? 0)}</Text>
                <Text color={statusColor(c)}>{'━'.repeat(gm?.bar ?? 1)}</Text>
                <Text color={C.faint}>{'·'.repeat(gm?.after ?? 0) + ' '}</Text>
                {clock(`lane-clock-${c.id}`, c.spawnedAt, c.endedAt, C.dim)}
              </Box>
            )
          })}
        </Box>
      )
    }
    const shown = cards.slice(-fit)
    const cardW = Math.max(20, Math.floor((w - (shown.length - 1)) / shown.length))
    const centers = shown.map((_, i) => i * (cardW + 1) + Math.floor(cardW / 2))
    return (
      <Box flexDirection="column" width={w}>
        {header}
        {rail('fan-out', running.length > 0, C.agent, w, centers)}
        <Box columnGap={1}>
          {shown.map((c, i) => {
            const isViewed = viewed === c.id
            const sameModel = !c.model || prettyModel(c.model) === modelName
            return (
              <Box
                flexDirection="column"
                borderStyle={isViewed ? 'double' : 'round'}
                borderColor={c.lastStop === 'max_tokens' ? C.warn : C.agent}
                borderDimColor={c.status !== 'running' && !isViewed}
                width={cardW}
                paddingX={1}
              >
                <Button key={`card-${c.id}`} plain label={titleLines(cardTitle(c), cardW - 7, cardW - 4)[0]} onPress={expandOnPress(c.id)} />
                <Text bold wrap="truncate">
                  {titleLines(cardTitle(c), cardW - 7, cardW - 4)[1]}
                </Text>
                <Text color={C.dim} wrap="truncate">
                  {sameModel ? c.type : `${c.type} · ${prettyModel(c.model)}`}
                </Text>
                <Text dimColor wrap="truncate">
                  {c.steps > 0 ? `ctx ${kTokens(c.ctx)} · out ${kTokens(c.out)} · ${c.steps} st` : 'starting…'}
                </Text>
                <Box>
                  <Text color={c.lastStop === 'max_tokens' ? C.warn : statusColor(c)}>
                    {cardW >= 26 ? `${glyph(c)} ${c.lastStop === 'max_tokens' ? 'max_tokens' : c.status} ` : `${glyph(c)} `}
                  </Text>
                  <Box flexShrink={0}>{clock(`card-clock-${c.id}`, c.spawnedAt, c.endedAt, C.dim)}</Box>
                </Box>
              </Box>
            )
          })}
        </Box>
        {rail('merge', running.length > 0, C.agent, w, centers, true)}
      </Box>
    )
  }

  const expandedCard = cards.find(c => c.id === v.expanded)
  const expandedPanel = (w: number) =>
    expandedCard ? (
      <Box flexDirection="column" borderStyle="single" borderColor={C.agent} paddingX={1} width={w}>
        <Text bold wrap="wrap">
          {expandedCard.description || expandedCard.type}
        </Text>
        <Text dimColor wrap="truncate">{`${expandedCard.type} · ${prettyModel(expandedCard.model)} · ${expandedCard.status} · ${expandedCard.steps} steps`}</Text>
        {expandedCard.tools.length === 0 ? <Text color={C.faint}>no tool calls yet</Text> : null}
        {expandedCard.tools.map(n => (
          <Text color={n.isError ? C.warn : C.text} wrap="truncate">
            {`${n.isError ? '✗' : '·'} ${n.text}`}
          </Text>
        ))}
        {expandedCard.answer ? (
          <Text dimColor wrap="wrap">
            {`» ${shorten(expandedCard.answer, 240)}`}
          </Text>
        ) : null}
      </Box>
    ) : null

  // ---- other loops (workflow agents, forks): ids that match no card
  const loopsPanel = (w: number) => {
    if (lp.length === 0) return null
    const active = lp.filter(l => isLoopActive(l, now)).length
    const dots = lp.slice(-Math.max(4, w - 38))
    return (
      <Box width={w}>
        <Text bold>other loops </Text>
        <Text dimColor>{`${lp.length} seen · ${active} active  `}</Text>
        {dots.map(l => (
          <Text color={isLoopActive(l, now) ? C.agent : l.isDone ? C.dim : C.faint}>{isLoopActive(l, now) ? '●' : l.isDone ? '✓' : '○'}</Text>
        ))}
      </Box>
    )
  }

  // ---- receipt: the turn now, or the last one
  const receiptPanel = (w: number) => {
    return (
      <Box flexDirection="column" borderStyle="round" borderColor={C.main} borderDimColor={!m.isRunning} paddingX={1} width={w}>
        {m.isRunning ? (
          <Box>
            <Text color={C.main} wrap="truncate">{`◐ back to ${modelName.toLowerCase()} · turn `}</Text>
            <Box flexShrink={0}>{clock('turn-clock', t.startedAt, null, C.main)}</Box>
            {w >= 60 ? <Text dimColor wrap="truncate">{` · ${plural(t.edits, 'edit')} · ${plural(t.errors, 'error')}`}</Text> : null}
          </Box>
        ) : r ? (
          <Text wrap="truncate">
            <Text color={r.reason === 'answer' ? C.gate : C.warn}>{r.reason === 'answer' ? '✓ ' : '✗ '}</Text>
            <Text>{`last turn ${fmtDuration(r.durationMs)} · ${plural(r.agents, 'agent')} · ${plural(r.edits, 'edit')} · ${plural(r.errors, 'error')}`}</Text>
            {r.costDelta !== null ? <Text color={C.main}>{` · +${fmtUsd(r.costDelta)}`}</Text> : null}
          </Text>
        ) : (
          <Text color={C.faint}>no turn finished yet</Text>
        )}
      </Box>
    )
  }

  // ---- tools: the busiest tools, their mean latency and recent failures
  const toolUnits = top.map(([name, st]) => {
    const mean = meanMs(st)
    const dots = badDots(st)
    return `${toolName(name)} ${mean === null ? '—' : `${(mean / 1000).toFixed(1)}s`}${dots > 0 ? ` ${'•'.repeat(dots)}` : ''}`
  })
  const toolsPanel = (w: number) =>
    isDesktop ? (
      <Box width={w} flexWrap="wrap" columnGap={2}>
        <Text>TOOLS</Text>
        {toolUnits.map(t => (
          <Text>{t}</Text>
        ))}
      </Box>
    ) : (
      <Box width={w}>
        <Text wrap="truncate">{`TOOLS  ${toolUnits.join('  ')}`}</Text>
      </Box>
    )

  // ---- turn: tests, the file under churn, aborts, and the gate's tallies
  const testsColor = deck.tests.light === 'pass' ? C.gate : C.warn
  const hotColor = hot && hot.edits >= HOT_FILE_WARN ? C.amber : C.text
  const hotText = hot ? `hot file ${lastSegments(hot.path)} ×${hot.edits}${hot.edits >= HOT_FILE_WARN ? ' ⚠' : ''}` : null
  const gateText = `gate file ${sumTotals(g.totals.file)} · shell ${sumTotals(g.totals.shell)} · ask ${s.ask}`
  const turnPanel = (w: number) =>
    isDesktop ? (
      <Box width={w} flexWrap="wrap" columnGap={3}>
        <Text bold>TURN</Text>
        {testsWord ? <Text color={testsColor}>{`tests ■ ${testsWord}`}</Text> : <Text dimColor>tests —</Text>}
        {hotText ? <Text color={hotColor}>{hotText}</Text> : null}
        <Text dimColor>{`aborts ${deck.aborts.count}`}</Text>
        <Text dimColor>{gateText}</Text>
      </Box>
    ) : (
      <Box width={w}>
        <Text wrap="truncate">
          <Text bold>TURN  </Text>
          {testsWord ? <Text color={testsColor}>{`tests ■ ${testsWord}`}</Text> : <Text dimColor>tests —</Text>}
          {hotText ? <Text color={hotColor}>{`   ${hotText}`}</Text> : null}
          <Text dimColor>{`   aborts ${deck.aborts.count}`}</Text>
          <Text dimColor>{`   ${gateText}`}</Text>
        </Text>
      </Box>
    )

  // ---- log: whatever rows the other panels leave, 4 to 8
  const oneLiners = panels.filter(q => q === 'prompt' || q === 'tools' || q === 'turn').length
  const agentRows = cards.length > 0 ? 1 + (hasCursorRow ? 1 : 0) : 0
  const used =
    2 + 5 + 6 + (v.gateOpen ? 5 : 0) + (cards.length > fitCards(colW) ? 3 + Math.min(6, cards.length) : 8) + (expandedCard ? 8 : 0) + (lp.length ? 1 : 0) + 3 + bandCost + oneLiners + agentRows
  const nLog = logRows(pv.bodyRows, used)
  const shownLines = (viewed ? lines.filter(l => l.agentId === viewed) : lines).slice(-nLog)
  const colorOf = (l: LogLine) =>
    l.kind === 'error' ? C.warn : l.who === 'main' ? C.main : l.who === 'gate' ? C.gate : l.who === 'you' ? C.text : C.agent
  // The name column fits the longest name on screen, capped so the message keeps room, with a two-space gap after it.
  const whoW = Math.min(LOG_WHO_MAX, Math.max(8, ...shownLines.map(l => l.who.length))) + 2
  const logPanel = (w: number) => (
    <Box flexDirection="column" borderStyle="round" borderColor={C.faint} paddingX={1} width={w}>
      <Text dimColor>{viewed ? 'session log · this agent' : 'session log'}</Text>
      {shownLines.length === 0 ? <Text color={C.faint}>nothing yet</Text> : null}
      {shownLines.map(l => (
        <Box>
          <Box width={10} flexShrink={0}>
            <Text color={C.faint}>{fmtClock(l.at)}</Text>
          </Box>
          <Box width={whoW} paddingRight={2} flexShrink={0}>
            <Text color={colorOf(l)} bold wrap="truncate">
              {l.who}
            </Text>
          </Box>
          <Text color={l.kind === 'error' ? C.warn : C.text} wrap={isDesktop ? 'wrap' : 'truncate'}>
            {l.text}
          </Text>
        </Box>
      ))}
    </Box>
  )

  const panelOf: Record<Panel, (w: number) => RenderElement | null> = {
    main: mainPanel,
    prompt: promptPanel,
    gate: gatePanel,
    agents: agentsPanel,
    tools: toolsPanel,
    turn: turnPanel,
    loops: loopsPanel,
    receipt: receiptPanel,
    log: logPanel,
  }

  // One-line panels are transparent to the flow: a connector links the bordered panels around them.
  const isOneLine = (q: Panel) => q === 'prompt' || q === 'tools' || q === 'turn'
  const isUnlinked = (q: Panel | undefined) => q === undefined || q === 'agents' || q === 'loops'
  const column = (ps: Panel[], w: number) => (
    <Box flexDirection="column" width={w}>
      {ps.map((q, i) => {
        const prev = ps.slice(0, i).filter(x => !isOneLine(x)).at(-1)
        const link = q === 'log' || isOneLine(q) || isUnlinked(q) || isUnlinked(prev) ? null : rail(`link-${q}`, m.isRunning, C.main, w)
        return (
          <Box flexDirection="column">
            {link}
            {panelOf[q](w)}
            {q === 'agents' ? expandedPanel(w) : null}
          </Box>
        )
      })}
    </Box>
  )

  // Desktop draws the agents' time axis as SVG under the panels.
  const svgLanes =
    Svg && cards.length > 0
      ? (() => {
          const rowH = 18
          const pxW = 520
          const geo = lanes(cards.slice(-10), now, 100)
          const rects = cards
            .slice(-10)
            .map((c, i) => {
              const gm = geo[i]
              const x = 150 + ((gm?.before ?? 0) / 100) * (pxW - 160)
              const wpx = Math.max(3, ((gm?.bar ?? 1) / 100) * (pxW - 160))
              const fill = c.status === 'running' ? SVG_COLORS.running : c.status === 'done' ? SVG_COLORS.done : c.status === 'failed' ? SVG_COLORS.failed : SVG_COLORS.other
              const label = shorten(cardTitle(c), 22).replace(/[<&>]/g, '')
              return `<text x="4" y="${i * rowH + 13}" font-size="11" fill="${SVG_COLORS.label}">${label}</text><rect x="${x}" y="${i * rowH + 4}" width="${wpx}" height="10" rx="3" fill="${fill}"/>`
            })
            .join('')
          const svgH = Math.min(10, cards.length) * rowH + 4
          return (
            <Svg
              source={`<svg xmlns="http://www.w3.org/2000/svg" width="${pxW}" height="${svgH}" viewBox="0 0 ${pxW} ${svgH}">${rects}</svg>`}
              alt={`${cards.length} agents on a time axis`}
              width={pxW}
              height={svgH}
            />
          )
        })()
      : null

  // Inline above the prompt (the terminal's main screen), the pane is a summary of at most 8 rows.
  const isMini = layout === 'mini' || (layout === 'auto' && pv.placement === 'inline')
  if (isMini) {
    const live = [...cards.filter(c => c.status === 'running'), ...cards.filter(c => c.status !== 'running').reverse()].slice(0, 3)
    const counts = ` ${s.rule} allowed · ${s.cleared} ${decider}${s.ask > 0 ? ` · ${s.ask} pending` : ''} · ${s.deny} denied`
    const strip = g.recent.slice(-Math.max(4, W - GATE_LABEL.length - 1 - counts.length))
    const mg = u.pct !== null ? gauge(u.pct, 6) : null
    const hasSignals = deck.prompt.status !== 'idle' || testsWord !== null || deck.aborts.count > 0 || hot !== null
    return (
      <Box flexDirection="column" width={W}>
        <Text wrap="truncate">
          <Text color={C.main} bold>
            {modelName}
          </Text>
          <Text color={m.isRunning ? C.main : C.dim}>{m.isRunning ? ' ● working' : ' ○ idle'}</Text>
          {mg ? <Text dimColor> · ctx </Text> : null}
          {mg ? <Text color={(u.pct ?? 0) >= 80 ? C.warn : C.main}>{mg.on}</Text> : null}
          {mg ? <Text color={C.faint}>{mg.off}</Text> : null}
          {mg ? <Text>{` ${Math.round(u.pct ?? 0)}%`}</Text> : null}
          {u.compactions > 0 ? <Text color={C.amber}>{` ⟲${u.compactions}`}</Text> : null}
          {hasCache ? <Text dimColor>{` · cache ${cachePct}%`}</Text> : null}
          {u.costUsd !== null ? <Text dimColor>{` · ${fmtUsd(u.costUsd)}`}</Text> : null}
        </Text>
        {strip.length > 0 ? (
          <Box>
            <Text dimColor>{`${GATE_LABEL.toLowerCase()} `}</Text>
            {strip.map(c => (
              <Text color={verdictColor(c)} dimColor={c.inSubagent}>
                {c.verdict === 'deny' ? '✗' : '■'}
              </Text>
            ))}
            <Text color={s.deny > 0 ? C.warn : s.ask > 0 ? C.amber : C.dim} wrap="truncate">
              {counts}
            </Text>
          </Box>
        ) : null}
        {live.map(c => (
          <Box>
            <Text color={statusColor(c)}>{`${glyph(c)} `}</Text>
            <Box width={Math.max(10, W - 30)}>
              <Text wrap="truncate">{cardTitle(c)}</Text>
            </Box>
            <Text dimColor>{c.steps > 0 ? ` ctx ${kTokens(c.ctx)} ` : ' '}</Text>
            {clock(`mini-clock-${c.id}`, c.spawnedAt, c.endedAt, C.dim)}
          </Box>
        ))}
        {cards.length > live.length ? (
          <Text color={C.faint} wrap="truncate">{`+${cards.length - live.length} more agents · /sessiondeck layout compact for all`}</Text>
        ) : null}
        {hasSignals ? (
        <Text dimColor wrap="truncate">
