import type { AgentCard, AgentSample, ContextSample } from '../types'
import { gridOrder, laneOf, stateOf, type Palette as ThemePalette, type TitlePart } from './core'
import type { Palette as RasterPalette } from './raster'

export type Grid = string[]
export type ChartInput = { context: ContextSample[]; history: AgentSample[]; cards: AgentCard[]; cursor: number | null; now: number; minutes: number }

export const CHART_COLORS: RasterPalette = {
  '.': null,
  c: 0x7dd3fc,
  t: 0xfcd34d,
  h: 0x3f4654,
  s: 0x6b7280,
  r: 0x3b82f6,
  d: 0x16a34a,
  e: 0xdc2626,
  u: 0xf59e0b,
  A: 0x93c5fd,
  B: 0xc4b5fd,
  C: 0x86efac,
  D: 0xfca5a5,
  E: 0x5eead4,
  F: 0xe5e7eb,
}

const DRACULA_COLORS: RasterPalette = {
  '.': null,
  c: 0x8be9fd,
  t: 0xf1fa8c,
  h: 0x44475a,
  s: 0x6272a4,
  r: 0xbd93f9,
  d: 0x50fa7b,
  e: 0xff5555,
  u: 0xffb86c,
  A: 0x8be9fd,
  B: 0xbd93f9,
  C: 0x50fa7b,
  D: 0xff79c6,
  E: 0xf1fa8c,
  F: 0xf8f8f2,
}

export const chartColors = (palette: ThemePalette): RasterPalette => (palette === 'dracula' ? DRACULA_COLORS : CHART_COLORS)

const LANE_BARS = 'ABCDEF'
const STATE_CHAR = { spawning: 's', running: 'r', done: 'd', error: 'e' } as const

export const blank = (width: number, height: number): Grid => Array.from({ length: Math.max(0, height) }, () => '.'.repeat(Math.max(0, width)))

const put = (grid: Grid, x: number, y: number, ch: string) => {
  const row = grid[y]
  if (row === undefined || x < 0 || x >= row.length || !Number.isInteger(x)) return
  grid[y] = row.slice(0, x) + ch + row.slice(x + 1)
}

const fillUp = (grid: Grid, x: number, from: number, to: number, ch: string) => {
  const height = grid.length
  for (let p = from; p < to; p++) put(grid, x, height - 1 - p, ch)
}

// Both charts span the session so far, at least a minute and at most `minutes`, so a young
// session fills the width and the two x axes agree.
const windowMs = (i: ChartInput): number => {
  const full = i.minutes * 60_000
  const ats = [...i.context, ...i.history].map(s => s.at)
  if (ats.length === 0) return full
  return Math.max(60_000, Math.min(full, i.now - Math.min(...ats)))
}

export const windowMinutes = (i: ChartInput): number => Math.max(1, Math.round(windowMs(i) / 60_000))

// Column x shows the latest sample before its end, so a sample holds until the next one replaces it.
const byColumn = <T extends { at: number }>(samples: T[], i: ChartInput, width: number): (T | null)[] => {
  const window = windowMs(i)
  const span = window / width
  const start = i.now - window
  return Array.from({ length: width }, (_, x) => {
    const end = start + (x + 1) * span
    let best: T | null = null
    for (const s of samples) if (s.at < end && (best === null || s.at >= best.at)) best = s
    return best
  })
}

export const contextChart = (i: ChartInput, width: number, height: number): Grid => {
  const grid = blank(width, height)
  byColumn(i.context, i, width).forEach((s, x) => {
    if (s === null) return
    if (s.compacted) return fillUp(grid, x, 0, height, 't')
    fillUp(grid, x, 0, Math.round((s.percent / 100) * height), 'c')
    put(grid, x, height - 1 - Math.round(s.cacheHit * (height - 1)), 'h')
  })
  return grid
}

export const historyChart = (i: ChartInput, width: number, height: number): Grid => {
  const grid = blank(width, height)
  const cols = byColumn(i.history, i, width)
  const y = Math.max(1, ...cols.map(s => (s === null ? 0 : s.running + s.done + s.error)))
  cols.forEach((s, x) => {
    if (s === null) return
    const r = Math.round((s.running / y) * height)
    const d = Math.round(((s.running + s.done) / y) * height)
    const e = Math.round(((s.running + s.done + s.error) / y) * height)
    fillUp(grid, x, 0, r, 'r')
    fillUp(grid, x, r, d, 'd')
    fillUp(grid, x, d, e, 'e')
  })
  return grid
}

type Placed = { card: AgentCard; index: number; x: number; y: number }
type Bar = { lane: number; y: number; to: number }
type Layout = { size: 4 | 2 | 1; placed: Placed[]; bars: Bar[]; dropped: number }

// Each lane starts a new cell row behind a 1 px bar; cell rows that fall below the area are dropped.
const layout = (cards: AgentCard[], width: number, height: number, size: 4 | 2 | 1): Layout => {
  const gap = size === 1 ? 0 : 1
  const step = size + gap
  const perRow = Math.floor((width - 2 + gap) / step)
  const rows = Math.floor((height + gap) / step)
  const ordered = gridOrder(cards)
  const placed: Placed[] = []
  const bars: Bar[] = []
  let row = 0
  let lane = -1
  let prev: string | null = null
  let col = 0
  ordered.forEach((card, index) => {
    const name = laneOf(card)
    if (name !== prev) {
      if (prev !== null) row++
      prev = name
      lane++
      col = 0
    } else if (col === perRow) {
      row++
      col = 0
    }
    if (perRow > 0 && row < rows) {
      const y = row * step
      placed.push({ card, index, x: 2 + col * step, y })
      const last = bars.at(-1)
      if (last !== undefined && last.lane === lane) last.to = y + size
      else bars.push({ lane, y, to: y + size })
    }
    col++
  })
  return { size, placed, bars, dropped: ordered.length - placed.length }
}

const SIZES = [4, 2, 1] as const

export const cellSize = (cards: AgentCard[], width: number, height: number): 4 | 2 | 1 =>
  SIZES.find(size => layout(cards, width, height, size).dropped === 0) ?? 1

export const agentGrid = (i: ChartInput, width: number, height: number): { grid: Grid; dropped: number } => {
  const grid = blank(width, height)
  const { size, placed, bars, dropped } = layout(i.cards, width, height, cellSize(i.cards, width, height))
  for (const b of bars) for (let y = b.y; y < b.to; y++) put(grid, 0, y, LANE_BARS.charAt(b.lane % LANE_BARS.length))
  for (const p of placed) {
    const isCursor = p.index === i.cursor
    const fill = isCursor && size < 4 ? 'u' : STATE_CHAR[stateOf(p.card)]
    for (let dy = 0; dy < size; dy++)
      for (let dx = 0; dx < size; dx++) {
        const isEdge = dx === 0 || dy === 0 || dx === size - 1 || dy === size - 1
        put(grid, p.x + dx, p.y + dy, isCursor && isEdge ? 'u' : fill)
      }
  }
  return { grid, dropped }
}

export type BandPanel = { key: 'context' | 'agents' | 'history'; width: number; grid: Grid }

// The title row loses the two border columns and its one column of left padding.
export const titleColumns = (p: BandPanel) => p.width - 3

export type TitleFacts = {
  contextPct: number | null
  cachePct: number | null
  compacted: boolean
  running: number
  done: number
  error: number
  dropped: number
  minutes: number
  peak: number
}

const pct = (n: number | null) => (n === null ? '—' : `${Math.round(n)}`)

// The short context form drops `%` so context, cache and the compaction mark all fit at 100% in the 60-column floor.
export const bandTitles = (f: TitleFacts): Record<BandPanel['key'], TitlePart[]> => ({
  context: [
    { swatch: { glyph: '■', ch: 'c' }, text: ` context ${f.contextPct === null ? '—' : `${pct(f.contextPct)}%`}`, short: ` ctx ${pct(f.contextPct)}` },
    { swatch: { glyph: '■', ch: 'h' }, text: ` cache ${f.cachePct === null ? '—' : `${pct(f.cachePct)}%`}`, short: ` cache ${pct(f.cachePct)}` },
    ...(f.compacted ? [{ swatch: { glyph: '▌', ch: 't' }, text: 'compact', short: '' }] : []),
  ],
  agents: [
    { swatch: { glyph: '■', ch: 'r' }, text: ` ${f.running} run`, short: ` ${f.running}` },
    { swatch: { glyph: '■', ch: 'd' }, text: ` ${f.done} done`, short: ` ${f.done}` },
    { swatch: { glyph: '■', ch: 'e' }, text: ` ${f.error} err`, short: ` ${f.error}` },
    ...(f.dropped > 0 ? [{ text: `+${f.dropped} off-grid`, short: `+${f.dropped}` }] : []),
  ],
  history: [
    { text: `history ${f.minutes}m`, short: `${f.minutes}m` },
    { text: `peak ${f.peak}`, short: `↑${f.peak}` },
  ],
})

// Each panel's grid is its width less the two border columns.
export const bandPanels = (i: ChartInput, width: number, height: number): { panels: BandPanel[]; dropped: number } => {
  if (i.cards.length === 0) return { panels: [{ key: 'context', width, grid: contextChart(i, width - 2, height) }], dropped: 0 }
  const c = Math.floor(0.4 * width)
  const g = Math.floor(0.3 * width)
  const h = width - c - g
  const agents = agentGrid(i, g - 2, height)
  return {
    panels: [
      { key: 'context', width: c, grid: contextChart(i, c - 2, height) },
      { key: 'agents', width: g, grid: agents.grid },
      { key: 'history', width: h, grid: historyChart(i, h - 2, height) },
    ],
    dropped: agents.dropped,
  }
}

