// The runtime ships these (RasterProps documents toBase64); lib es2023 has no types for them.
declare global {
  interface Uint8Array { toBase64(): string }
  interface Uint8ArrayConstructor { fromBase64(base64: string): Uint8Array }
}

export type Palette = Record<string, number | null>

export const DEFAULT_COLOR = 0x01000000

const UPPER = 0x2580
const LOWER = 0x2584
const SPACE = 0x20

type Color = number | null

const cell = (top: Color, bottom: Color): [number, number, number] => {
  if (top === null) return bottom === null ? [SPACE, DEFAULT_COLOR, DEFAULT_COLOR] : [LOWER, bottom, DEFAULT_COLOR]
  return [UPPER, top, bottom ?? DEFAULT_COLOR]
}

const colorAt = (row: string | undefined, x: number, palette: Palette): Color =>
  palette[row?.[x] ?? '.'] ?? null

export const encodeCells = (grid: readonly string[], palette: Palette): { columns: number; rows: number; cells: string } => {
  const columns = grid[0]?.length ?? 0
  const rows = Math.ceil(grid.length / 2)
  const words = new Uint32Array(columns * rows * 3)
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < columns; x++) {
      const top = colorAt(grid[2 * y], x, palette)
      const bottom = colorAt(grid[2 * y + 1], x, palette)
      words.set(cell(top, bottom), (y * columns + x) * 3)
    }
  }
  return { columns, rows, cells: new Uint8Array(words.buffer).toBase64() }
}

export const decodeCells = (cells: string): Uint32Array => {
  const bytes = Uint8Array.fromBase64(cells)
  return new Uint32Array(bytes.buffer, bytes.byteOffset, bytes.byteLength / 4)
}

export const upscale2x = (grid: readonly string[]): string[] =>
  grid.flatMap(row => {
    const wide = [...row].map(c => c + c).join('')
    return [wide, wide]
  })

