import type { Grid } from './charts'
import type { Palette } from './raster'

// A grid pixel is half a terminal cell, about square; 7 px keeps a cell inside the desktop's code-font advance.
export const CELL_PX = 7

const SEG_W = 6
const SEG_GAP = 2
const SEG_H = 8

export const hex = (n: number) => `#${n.toString(16).padStart(6, '0')}`

/** The band's palette grid as SVG: one rect per run of a color along a row, in grid units. */
export const gridSvg = (grid: Grid, palette: Palette): string => {
  const columns = grid[0]?.length ?? 0
  const rows = grid.length
  const rects: string[] = []
  grid.forEach((row, y) => {
    let x = 0
    while (x < row.length) {
      const ch = row.charAt(x)
      let end = x + 1
      while (end < row.length && row.charAt(end) === ch) end++
      const color = palette[ch] ?? null
      if (color !== null) rects.push(`<rect x="${x}" y="${y}" width="${end - x}" height="1" fill="${hex(color)}"/>`)
      x = end
    }
  })
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${columns * CELL_PX}" height="${rows * CELL_PX}" viewBox="0 0 ${columns} ${rows}" preserveAspectRatio="none" shape-rendering="crispEdges">${rects.join('')}</svg>`
}

type Gauge = { on: string; off: string }

const segments = (g: Gauge) => [...g.on].length + [...g.off].length
export const gaugeWidth = (g: Gauge) => Math.max(0, segments(g) * (SEG_W + SEG_GAP) - SEG_GAP)
export const GAUGE_HEIGHT = SEG_H + 2

/** A text gauge (`▰▰▱`) as SVG segments: filled in `on`, outlined in `off`. */
export const gaugeSvg = (g: Gauge, on: string, off: string): string => {
  const full = [...g.on].length
  const segs = Array.from({ length: segments(g) }, (_, i) => {
    const x = i * (SEG_W + SEG_GAP)
    return i < full
      ? `<rect x="${x}" y="1" width="${SEG_W}" height="${SEG_H}" rx="1.5" fill="${on}"/>`
      : `<rect x="${x + 0.5}" y="1.5" width="${SEG_W - 1}" height="${SEG_H - 1}" rx="1.5" fill="none" stroke="${off}"/>`
  })
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${gaugeWidth(g)}" height="${GAUGE_HEIGHT}" viewBox="0 0 ${gaugeWidth(g)} ${GAUGE_HEIGHT}">${segs.join('')}</svg>`
}

