      "description": "theme follows your Claude Code theme (light, dark, colour-blind); pastel and dracula are fixed colours tuned for dark terminals",
      "type": "string",
      "options": [
        "theme",
        "pastel",
        "dracula"
      ],
      "default": "theme"
    },
    "openOnStart": {
      "title": "Open on start",
      "description": "Open the pane when a session starts",
      "type": "boolean",
      "default": true
    },
    "statusLine": {
      "title": "Status line",
      "description": "Show context, agents and denials in the status line",
      "type": "boolean",
      "default": true
    },
    "testPattern": {
      "title": "Test command pattern",
      "description": "Regular expression (case-insensitive) for Bash commands that count as a test run",
      "type": "string",
      "default": "\\b(vitest|jest|pytest|go test|cargo test|npm test|pnpm test|bun test|mocha)\\b"
    },
    "historyMinutes": {
      "title": "History minutes",
      "description": "Minutes shown by the context and agent history charts (1-30)",
      "type": "number",
      "default": 30
    },
