files.types/index.d.ts:
export type Bucket = 'file' | 'shell' | 'other'

/** rule: settings allowed it. ask: put to the decider, outcome pending. cleared: asked, then ran. deny: refused. */
export type Verdict = 'rule' | 'ask' | 'cleared' | 'deny'

export type Main = { model: string; effort: string; mode: string; steps: number; isRunning: boolean }

export type Usage = {
  pct: number | null
  tokens: number | null
  window: number
  costUsd: number | null
  limits: { kind: string; pct: number }[]
  compactions: number
  lastCompactAt: number | null
}

export type Check = {
  id: string
  tool: string
  bucket: Bucket
  verdict: Verdict
  inSubagent: boolean
  detail: string
  at: number
}

export type Tally = { rule: number; ask: number; cleared: number; deny: number }

export type Gate = { recent: Check[]; totals: Record<Bucket, Tally> }

export type ToolNote = { tool: string; text: string; isError: boolean }

export type AgentCard = {
  id: string
  type: string
  model: string
  description: string
  status: string
  spawnedAt: number
  endedAt: number | null
  /** The agent's context now: input + cache read + cache write of its latest step. */
  ctx: number
  /** Output tokens summed over its steps. */
  out: number
  steps: number
  lastStop: string | null
  tools: ToolNote[]
  answer: string
  parentAgentId: string | null
}

/** A model loop whose id matches no card: a workflow agent, a compaction or a memory fork. */
export type Loop = { id: string; steps: number; firstAt: number; lastAt: number; isDone: boolean }

export type LogLine = {
  at: number
  who: string
  text: string
  agentId: string | null
  kind: 'info' | 'error' | 'done'
}

export type Turn = {
  edits: number
  errorStreak: number
  errors: number
  startedAt: number
  costAtStart: number | null
  /** Agents this session when the turn started, so the receipt counts the turn's own. */
  agentsAtStart: number
}

export type Receipt = {
  durationMs: number
  agents: number
  edits: number
  errors: number
  costDelta: number | null
  reason: string
  /** Absent on a receipt saved before this field existed. */
  startedAt?: number
}

export type Layout = 'auto' | 'compact' | 'wide' | 'mini'

export type View = { expanded: string | null; gateOpen: Bucket | null; layout: Layout | null; cursor: number | null }

export type PromptStatus = 'idle' | 'running' | 'done' | 'aborted'

export type Prompt = { text: string; startedAt: number | null; status: PromptStatus }

export type Cache = { read: number; input: number; creation: number }

export type ToolStat = { calls: number; errors: number; denies: number; recentMs: number[]; recentOk: boolean[]; lastOk: boolean }

export type Tools = Record<string, ToolStat>

/** File path to edits this turn. */
export type HotFiles = Record<string, number>

export type Tests = { light: 'off' | 'pass' | 'fail'; pass: number; fail: number; lastAt: number | null }

export type Aborts = { count: number; at: number[]; turnIds: string[] }

export type AgentState = 'spawning' | 'running' | 'done' | 'error'

export type AgentTally = { spawning: number; running: number; done: number; error: number }

export type AgentSample = { at: number; running: number; done: number; error: number }

/** `byType` holds only the tallies of cards the cap dropped. */
export type Agents = { byType: Record<string, AgentTally>; history: AgentSample[] }

export type ContextSample = { at: number; percent: number; cacheHit: number; compacted: boolean }

export type Context = { history: ContextSample[]; compactPending: boolean; lastPercent: number | null }

declare module 'claude-code' {
  interface PluginState {
    'sessiondeck': {
      meta: { schemaVersion: number }
      main: Main
      usage: Usage
      gate: Gate
      agents: AgentCard[]
      loops: Loop[]
      log: LogLine[]
      turn: Turn
      receipt: Receipt | null
      view: View
      prompt: Prompt
      cache: Cache
      tools: Tools
      hotFiles: HotFiles
      tests: Tests
      aborts: Aborts
      agentStats: Agents
      context: Context
    }
  }
}
